window.TAROT_CARDS = [
  // ===== 大阿卡那 Major Arcana (mj00 - mj21) =====
  {
    id: "mj00", img: "mj00.jpg", arcana: "major", rank: "0", name: "愚者", en: "The Fool", glyph: "🃏",
    upright: { kw: "新的开始 / 自由 / 天真", love: "他赤脚踏上新径，你也别急着给缘分定名分。先约一场能边走边聊的散步，像谷中河水那样自然往前。包袱挂在杖头就好，别把过往的旧账也背上路。", study: "像少年迈向崖边那样，新方向入门贵在敢开始。杖头只挂一个小包袱，试水期别囤满桌的资料。野草地里花色繁多，每月留半天整理尝到的收获。", career: "把行囊往杖头一挂就上路，转岗前先轻装试接小活。临行前把粮袋装满，最低保障算清了再谈冒险。日光当头，头三个月多问少承诺，把小事做成闭环。" },
    reversed: { kw: "冒失 / 停滞不前 / 逃避现实", love: "走到崖边还望着天，这一步该低头看路了。先把杖上的旧包袱解开，上一段的情绪别转嫁给眼前人。白玫瑰经不起随意拿捏，想清楚自己要什么再伸手。", study: "莽莽撞撞冲出草地，三分钟热度的计划先拆小。包袱塞满没翻过的资料，倒出来只留一册在手边。悬崖边不该闭眼快走，报新课前先把要求读明白。", career: "崖下的风景看着诱人，没算清退路就先别跳。行囊空着上路会缺口粮，离职前留出一笔备用金。白狗能引路，下家的合同条款要找人问明白。" }
  },
  {
    id: "mj01", img: "mj01.jpg", arcana: "major", rank: "1", name: "魔术师", en: "The Magician", glyph: "🎩",
    upright: { kw: "创造 / 主动 / 资源整合", love: "像他举杖引下天光，想约见面就把话直接说清。石桌上的杯与剑各放其位，约会也值得提前安排细节。头顶的光环无限延伸，两周之内把这阵热情变成一次行动。", study: "四件法器摆成一排，资料工具和时间也该各归其位。举杖的人只盯一处，攻坚清单一次只推进一项。剑在桌上是拆解，遇到难题就切成小段逐个划开。", career: "桌上的杯剑杖币一样不缺，你手里的人脉预算也够开局。他敢把杖举向天空，核心任务此刻就该开口去争。远山与城堡都在视野里，整合资源后定期向众人同步进展。" },
    reversed: { kw: "混乱 / 拖延 / 才能内耗", love: "把指向天地的手收回来，先核对承诺与行动差了几步。杖举得再高，不落下就只是姿势，承诺要落成一件小事。光环悬在头顶落不到手里，修复期最忌再许新的大话。", study: "法器摆了一桌等于什么都没练，笔记再精美也要做题。先把桌面清成一张，多余的工具与资料收出视线。光环断了就没魔力，连续三天做完同一件小事再谈天赋。", career: "杯剑杖币全在桌上却摆错了阵，资源好也可能用反方向。把剑收回鞘里，精力挪回最核心的那项产出。开口之前先想清楚能兑现什么，没底气的承诺会反噬自身。" }
  },
  {
    id: "mj02", img: "mj02.jpg", arcana: "major", rank: "2", name: "女祭司", en: "The High Priestess", glyph: "🌙",
    upright: { kw: "直觉 / 静默 / 内在智慧", love: "她垂目读卷，心里那点不对劲先别说服自己忽略。黑柱与白柱之间自有分寸，找个平和的时机把疑问问清。脚边的雾气夜里最浓，深夜的直觉记下来白天再核实。", study: "她独坐柱间不理会外界，长内容正适合一个人慢慢啃。卷轴摊在膝上才读得细，把最难的内容排进独处时段。黑柱白柱一明一暗，学一段再合卷回想，深浅自然分明。", career: "她眼皮轻阖却什么都听见，会上的沉默先把立场摸清。卷轴不摊开给别人看，判断先写进私人笔记等时机。足下水声先于言语，等局势浮出水面再交出方案。" },
    reversed: { kw: "压抑 / 忽视直觉 / 秘密", love: "黑白柱立在身前身后，你光站着不动，冰就永远结着。先把最小的一件事说出口，情绪早讲是沟通晚讲成控诉。石榴藏在幕布后数不清，疑心对方时先去核实事实。", study: "两柱之间只容一身，一次只处理一科，专注会慢慢回来。卷轴上的字读不进去时，先把担心的内容逐条写下核对。每天留一段不碰手机的静时，让心像脚边的水面沉下来。", career: "黑柱挡住的传闻，绕不开就直接找当事人谈。白柱下的事实别只留给自己，该同步的进度按时公开。背后幕布上石榴数不全，打听不到的事先别急着下结论。" }
  },
  {
    id: "mj03", img: "mj03.jpg", arcana: "major", rank: "3", name: "皇后", en: "The Empress", glyph: "🌹",
    upright: { kw: "丰盛 / 滋养 / 感官之美", love: "她掌心的金粉落在麦穗上，爱意也该落在每一顿用心的饭里。裙上的石榴一颗颗饱满，共同布置住处最能悄悄升温。溪水绕着麦田走，顺路接送这类小事比隆重表白更养感情。", study: "整片熟麦在等收割，文科与艺术的内容动手做比反复背更快。蝴蝶绕着她的裙摆，把学习角落布置舒服，状态会被环境养住。她赤脚踩土，身体状态直接连着记忆，别拿熬夜换学习时长。", career: "她张开的两手撒出金粉，对自己人慷慨换得来长久合作。溪流转弯处仍有睡莲，交付做得好看好用会自己引来资源。丰收时别忘了盾石旁的账，回头复盘成本才守得住仓廪。" },
    reversed: { kw: "依赖 / 挥霍 / 创造力阻塞", love: "石榴穿满裙身也压得慌，包办一切的爱会变成双方的负担。溪水漫过田埂就失了规矩，留出空间让对方也来照顾你。付出换不来回应时，把金粉收回来先养自己的园地，怨气自淡。", study: "麦田金黄却懒得下镰，舒适区待久了连书都拿不稳。蝴蝶一引就走神，零食和手机放到另一个房间去。溪边躺卧虽舒服，单次学习先缩到二十分钟再谈强度。", career: "满园石榴看着热闹，砍掉华而不实的开销，钱投给出活的环节。盾牌立在田头是提醒，先备好底线再谈体面排场。长期过劳的人像旱了的麦田，主动减负，创造力才重新返青。" }
  },
  {
    id: "mj04", img: "mj04.jpg", arcana: "major", rank: "4", name: "皇帝", en: "The Emperor", glyph: "👑",
    upright: { kw: "秩序 / 权威 / 稳固根基", love: "他坐稳石座手握权杖，承诺按部就班的关系最让人心安。扶手上的羊头盯着日子，纪念日与见家长都提前排进日程。台阶下的向日葵朝着光，偶尔放下主见让对方安排一次。", study: "石座一层层垒得稳，作息与科目也该固定成一张日程表。权杖立定不打晃，规则写在纸上比全靠意志力省力。铠甲一片一片编成，错题定期回顾，基础跟着秩序往上走。", career: "他端坐高处统观群山，流程权责节点定清，推诿自然减少。权杖指向天空也压住自己，立规矩时把自己先放进去。金球托在左手不握死，交代背景与理由，命令才有来由。" },
    reversed: { kw: "固执 / 控制欲过强 / 僵化", love: "羊头扶手再稳也是牢椅，把决定权分一半出去透透气。从最小的那件事开始放手，让对方领一次路。台阶一层层走下来，有意见时先听对方把话讲完。", study: "羊头的固执要不得，同一类题刻意换两三种解法去练。石座坐久了会凉，老师的答案也允许多问一层为什么。铁甲防身也防新东西，把讲解当参考而不是标准。", career: "座边羊头各守一边，决策前专门设一个反对意见的环节。红袍威严也隔人，规则定死之前留出可以商量的缝。石阶要让人走得上来，把反馈通道打开，人心才不会散。" }
  },
  {
    id: "mj05", img: "mj05.jpg", arcana: "major", rank: "5", name: "教皇", en: "The Hierophant", glyph: "📿",
    upright: { kw: "传承 / 指导 / 共同信念", love: "他抬手降福，两旁的修士低头同礼，被祝福的关系更有支撑。阶前交叉的金钥匙交给彼此，公开的承诺让感情更稳。适合一起见亲友、参加仪式，谈钱谈未来都不别扭。", study: "有长者执杖引路，系统课程从头跟到尾比四处旁听扎实。双柱之间的石台供人俯仰，正统解法往往就是最短的那条路。领了祝福也要自己走路，每章合卷复述一遍才算数。", career: "长者伸手一指，两把金钥匙横在阶前，行业规矩与手艺要同时握住。得到提携要拿成果回报，人情与专业得同时立住。按流程做事容易赢得信任，节点上的汇报别省。" },
    reversed: { kw: "教条 / 质疑 / 另辟蹊径", love: "钥匙交叉搁在阶上，门却没人肯开，形式吵不完，真心没处放。先把两个人想要的生活对齐，再决定要不要向外界解释。旁人的常态不是你们的答案，心里怎么想先说给对方听。", study: "柱廊之下不止一条路，正统方法走不通就换一条验证。对每个结论多问一层依据，能自己推导出来才算掌握。换一种说法把知识讲给外人听，理解的漏洞立刻显形。", career: "金钥匙锈在了台阶上，前辈的做法照搬到底，环境一变就失了灵。质疑陈规之前先在体系内做出成绩，说服力足得多。新方法先做小样本验证，用结果代替会上无休止的争论。" }
  },
  {
    id: "mj06", img: "mj06.jpg", arcana: "major", rank: "6", name: "恋人", en: "The Lovers", glyph: "💞",
    upright: { kw: "结合 / 选择 / 价值契合", love: "像牌中相贴的掌心，心动对上节拍，关系自然成立。上方的天使张开双翼却不出手，爱情终究要自己选。若心里已有倾向，别等对方先开口，主动一点这段就活了。", study: "牌下那条穿谷的小溪在提醒，有真兴趣引路，再远也走得动。两棵树一边结果一边烧，选方向前先把得失各列一条看清。选完就往前走一段再回头评判，反复横跳最耗热情。", career: "合拍的事业伙伴像画里对视的两人，坦率得不用设防。一条稳如挂果的枝，一条烈如火烧的树，面临两条路时先问本心。价值观一致时，分工可以少谈条款多谈信任。" },
    reversed: { kw: "犹豫 / 分裂 / 关系失衡", love: "掌心没有贴上，是有人悄悄收回了手。缠树的蛇在耳边低语，别把一时心动误读成深知。怕选错的心气比选择本身更消耗，做完决定先走一段再说。", study: "光被云挡住不是消失，兴趣只是暂时被遮住了。把想要的和不甘心的各写一张清单，那是两回事。别再收集所有人的意见，挑一条路先试两周。", career: "两棵树各站一边，你不表态就会被两边当阵地。不合拍的合作别急着缝补，把诉求摊开谈一次。离开不是认输，是把相贴的掌心收回到自己身上。" }
  },
  {
    id: "mj07", img: "mj07.jpg", arcana: "major", rank: "7", name: "战车", en: "The Chariot", glyph: "🏇",
    upright: { kw: "意志 / 凯旋 / 掌控方向", love: "他双手执缰站上金车，认定了就主动推进见面与确定关系。星芒悬在头顶亮得笃定，把追求落到确定的时间和地点。遇到阻力先核对目标是否一致，而不是一味加鞭。", study: "双狮腾空的劲头全使在一处，备考攻坚最忌分心。车轮一圈圈压过草地，每周做一次小结，防止跑快了自己跑偏。城墙近在眼前，冲刺期也留一晚睡足觉。", career: "金车碾过草地直奔城门，项目在你的牵引下明显加速。一黑一白两兽合力，缰绳不能松，关键节点交给别人复核一次。星芒照着前路，往前赶时别被途中的噪音一次次改道。" },
    reversed: { kw: "失控 / 挫败 / 方向迷失", love: "两兽各朝一边发力，车在原地打转，一方要冲一方要缓。缰绳勒得越紧越容易翻车，追得太急先松两扣。若方向根本相反，及时下车比一路硬拽更省彼此。", study: "双狮拉扯，车轮陷进草里，计划排得太满反而整体趴窝。把周期拆短，每三五天设一个确实够得着的小目标。星芒再亮也照不醒打盹的人，状态差时只保基础题。", career: "城还在远处，星还在天上，方向理清楚再重新执缰。双狮各奔一方时，把其余任务延后并告知相关的人。遇挫别急着改道，先看清是能力缺口还是路径出了问题。" }
  },
  {
    id: "mj08", img: "mj08.jpg", arcana: "major", rank: "8", name: "力量", en: "Strength", glyph: "🦁",
    upright: { kw: "勇气 / 柔韧 / 以柔克刚", love: "她跪坐草间双手轻托狮吻，争吵时先接住情绪再讲道理。狮子颈上绕满白玫瑰，温柔的陪伴能驯服最烈的脾气。忍太久会一次爆发，有想法就温和而清楚地讲出来。", study: "她不掰狮口只轻轻一托，难题别硬磕，拆开步骤慢慢磨。玫瑰花冠一圈圈绕上鬃毛，每天留固定时间与难点相处。焦虑上头时先做两分钟最简单的部分，像她先把手放上狮吻。", career: "她单膝点地却气场十足，面对强势的同事不必硬碰。鬃毛上的玫瑰是众人递来的敬意，把功劳分给协作者，号召力自然上来。夕阳把草原染金，长期承压也要有出口，定期复盘与运动。" },
    reversed: { kw: "自我怀疑 / 失控 / 退缩", love: "手一抖狮口便合上，情绪上头的瞬间，最亲的人最容易被咬。自我怀疑时别反复索要保证，先把注意力放回自己身上。若长期被这段相处消耗，选择离开同样是一种力量。", study: "玫瑰冠掉了再编就是，记录连续完成的天数，坚持本身是燃料。还没伸手就先怕被咬，难题翻到一半就觉得自己不行。把大目标换成今天确实能做完的一件小事，像她只托住狮吻不碰獠牙。", career: "狮子认得她的手，底气靠一次次成功交付攒回来。被催促时手一松，狮口就合上，一句气话可能抵过全部努力。快要失控时先离开现场十分钟，回来再作回应。" }
  },
  {
    id: "mj09", img: "mj09.jpg", arcana: "major", rank: "9", name: "隐士", en: "The Hermit", glyph: "🏮",
    upright: { kw: "内省 / 沉淀 / 求索之道", love: "雪山顶上那盏提灯只照亮一小圈，你也先把自己照明白再谈靠近。独处不是熄灯，是把喧哗调小，听清心里那句真话。想约对方深谈，挑夜里月色那样的安静时刻，别在人群里问。", study: "隐士举灯只为脚下这一步，复习也别贪多，每晚弄透一个小专题。长杖点地一步一步算数，把厚书拆成每日的薄页，进度自然可观。星光下的寂静是资源，关掉推送，给自己两段完整的深潜时间。", career: "提灯的光晕不大，却足够照亮手里的路，眼下适合做总结与沉淀。退到雪山高处看全局，把手法整理成手册，幕后价值反而更醒目。老者的智慧在杖尖落地有声，找一位前辈深谈，胜过独自摸索半年。" },
    reversed: { kw: "孤立 / 封闭 / 过度避世", love: "灯若只照自己，屋里的人会以为你把她关在了山外。想独处就直说期限，一句这周需要安静，比整周不回消息体面。月亮再清冷也挂着星星，留一盏灯给想靠近你的人。", study: "灯举得再高，照的也只是自己画的那个圈，方向早偏了。每周留一晚下山走走，对照大纲和真题，看看路线有没有走歪。星空辽阔，问一句比闷想一天划算，找老师或同学戳破盲区。", career: "灯光只够一个人取暖的话，团队的需要就永远落在暗处。隐退太久，名单上会慢慢没有你的名字，关键讨论务必到场。常走走下山的路，认领一次协作任务，露面本身就是被考虑的前提。" }
  },
  {
    id: "mj10", img: "mj10.jpg", arcana: "major", rank: "10", name: "命运之轮", en: "Wheel of Fortune", glyph: "☸️",
    upright: { kw: "转机 / 周期 / 顺势而动", love: "轮顶的王者端坐不动，等的就是顺势伸手的人，别错过窗口。云层里那只鹰盯准了就俯冲，想回应对方时干脆一点。轮子一圈圈转，顺境时多攒共同经历，低谷才有存货可撑。", study: "读书的天使不慌不忙，把节奏定成可持续的周期，比突击更管用。轮盘转到顺位的时候加量最划算，趁手感好集中攻最弱那科。符文刻在轮缘转一圈亮一次，错题过完一周再回头清一遍。", career: "持剑的斯芬克斯守着机会的入口，把材料备齐再出手，胜算更厚。巨轮启动，此前的积累开始被看见，新项目来了就先进局占位。转动的轮从不等人准备好，把成功拆成可复用的动作才守得住。" },
    reversed: { kw: "厄运循环 / 失控 / 抗拒变化", love: "那蛇顺着轮缘往下滑，旧情绪也在往下带，先停掉熟悉的反应。鹰在云上看清了才扑，感觉不对时别急着定性，等轮势稳一点再选。刻满字的轮缘转不回昨天，破局先破执念，换回应才有新结果。", study: "狮子的书是打开的，请别人看看你的笔记，错处一眼就现形。再用力也抽不动倒转的轮，先停下复盘，别单纯延长时长。把低潮当成一次体检，对照大纲找出真正脱节的那一环。", career: "斯芬克斯的剑只给有准备的人开路，趁空档把条件补齐。云上的鹰早已俯冲过一轮，下一个关键节点提前标进日程。别学那条往下滑的蛇较劲，抗拒已发生的变化只会损耗更重。" }
  },
  {
    id: "mj11", img: "mj11.jpg", arcana: "major", rank: "11", name: "正义", en: "Justice", glyph: "⚖️",
    upright: { kw: "公正 / 因果 / 理性裁决", love: "天平两端持平的样子，就是关系该有的谈法，把付出摆上明处。裙上的蝴蝶轻得像情话，公道之外也要留情分，别赢了账目输了人。两柱之间的位置最稳，约一次对等的长谈，把期待说清楚。", study: "脚边的白百合开得不急，薄弱处慢慢补，因果自会结账。剑锋一样直的细则摆在那里，自测逐条对照，别凭印象估分。按棋盘格推进，时间留给分值高又没把握的板块。", career: "红玫瑰摆在明处，报酬别只口头承诺，白纸黑字落定最稳。天平与剑各在一手，权衡和决断可以并行，把条款写明白。该争取的像剑一样直说，留好证据链，讲规则比讲情绪有力。" },
    reversed: { kw: "失衡 / 偏颇 / 逃避责任", love: "秤盘一边高一边低的时候，这段关系已经在偷偷记账了。百合与玫瑰各开各的，把不平衡摊开说一次，再决定往哪边加砝码。先停止追加付出，把空出的那格留给对方补位。", study: "脚边的花从不挑格子开，各科都留出一格时间，偏见才钻不进来。剑该落下时别犹豫，回避的那科正是总分的瓶颈，先啃最小一章。别拿印象当结论，让同学批一次卷子，差距立刻显形。", career: "天平若斜了，口头承诺和纸面条款就会露出两张脸。棋盘上输了这局还有下一局，留好证据，等规则替你说话。签字前把条款逐条过剑，凡承诺都要求落成文字。" }
  },
  {
    id: "mj12", img: "mj12.jpg", arcana: "major", rank: "12", name: "倒吊人", en: "The Hanged Man", glyph: "🙃",
    upright: { kw: "换位 / 等待 / 以退为进", love: "倒挂的人不挣扎，头朝下反而看清了世界，争执时先换立场。秋叶落一阵才见枝干，关系降温几天，才看得出谁在守着。头后的光环安静发亮，等待期把自己安顿好，回头时才有新面貌。", study: "系在树上的绳结没有勒疼他，卡住的题放半天再回看，结会自己松。远山在倒挂者眼前反而更清楚，退一步再看书，框架比细节先亮。倒着看的世界换了方向，把解题讲给别人听，盲点立刻现形。", career: "树冠落下的叶子替他计时，等待有期限，转机来了才有落点。让出那只脚的力气，换来的是更稳的悬挂点，短期利益可换位置。光环只给沉得住气的人，让一步之前先算清让掉的是什么。" },
    reversed: { kw: "僵持 / 无谓牺牲 / 抗拒", love: "绳子若再紧一分就不是修行是消耗，熬干自己换不来感激。落叶铺了一地也不见回应时，把该承担的事分回给对方。先分清是自愿还是讨好，再谈这段要不要继续往下挂。", study: "半小时解不出就换路，绳结不是荣誉，别把它当坚持的勋章。远山不会因为盯着它而挪近，换一种讲法重学，思路才活。设一个止损点，卡住就求助，方向错了越努力亏得越多。", career: "树上的绳结解铃还须系铃人，不敢换岗时先练一次换位提案。别再拿奉献感当工资，把付出换算成成果再去谈条件。落叶一季一季地换，僵持的局面也能动一小步试试水温。" }
  },
  {
    id: "mj13", img: "mj13.jpg", arcana: "major", rank: "13", name: "死神", en: "Death", glyph: "🦋",
    upright: { kw: "彻底终结 / 蜕变 / 断舍离", love: "黑旗上只绣一朵白花，告别也可以干净，旧模式谢幕不必难看。白马从旧矛盾上跨过，允许自己难过，但别急着用新人填空位。那个头顶发光的孩子站在原地，空出来的位置先留给自己想清楚。", study: "骑士不再修补旧盔甲，笔记体系该删就删，重搭比缝补省力。废墟留在背景里，旧资料归档就好，按最新大纲重列框架。黑旗上的白花是转轨的记号，越早承认走错，损失越小。", career: "骑士离场时盔甲仍然整齐，交接做得体面，口碑会被下家看见。老业务像倒地的君王，守残局不如把手艺迁到新方向。黑与白同在一面旗上，结束和开始可以同时成立，别只看到失去。" },
    reversed: { kw: "执念 / 迟迟不结 / 抗拒转变", love: "枯树不肯落叶才最难熬，先把日常重新填满，答案自会清晰。旗子已经立起人却还在回头，反复联络旧人只会把自己拖在原地。倒地的君王不必再被摇醒，翻检旧记录的动作先停下来。", study: "小白花开在翻新过的草地上，从最陌生的一章先补起。盔甲都落地了还在翻旧笔记，过时的内容占着新知识的格子。废墟不拆就盖不了新房，按新大纲先列出从没碰的部分。", career: "废墟上的砖还能砌新墙，旧岗位的技能换个行业重新标价。骑士的马不会等你想完，环境在变时守着熟岗只会越守越窄。把结束当成一次交接，经验整理成可迁移的清单。" }
  },
  {
    id: "mj14", img: "mj14.jpg", arcana: "major", rank: "14", name: "节制", en: "Temperance", glyph: "⏳",
    upright: { kw: "平衡 / 调和 / 细水长流", love: "两只金杯之间的水线不断不溢，相处的节奏也该这样匀。天使的翅膀一边都不偏，见面与独处都留出位置，感情才养得稳。彩虹出现在雨后不急不躁，稳定的表达比一时的浓烈更让人安心。", study: "水从一个杯子匀到另一个，强弱科目交替着复习，谁也不被晾着。天使不急不慢地倾倒，把任务拆成每日的均量，比突击贴合记忆。彩虹要等水汽和阳光配比恰好，学到留一点余量再停手。", career: "彩虹的每种颜色都保留，资源分配留一成机动，突发才砸不出窟窿。跨方的诉求像两杯之水，被你调和进同一个方案，推进不必靠施压。双翼展开覆盖两端，协调类工作正适合现在，把人调和好就是价值。" },
    reversed: { kw: "失衡 / 极端 / 缺乏耐心", love: "断流的河床露着石头，过度付出与突然冷漠之间，先处理自己的失衡。翅膀只顾一边飞，忙碌时彻底失联，对方只能在猜测里打转。天使的脚步停在溪边，把可用的时间提前讲明，再谈靠近。", study: "一杯倒得太满一杯空着，一天学到虚脱再歇好几天，进度在两极间晃。水线断了就没有彩虹，极端用功之后必有倦怠，休息要写进计划。山口的水讲究细水长流，把长期目标折回每日的均量。", career: "水从杯沿泼出去，预算一次押光，中间没有缓冲，小事故就演变成危机。单翼撑不起身体，把目标拆成可交付的小步，宁可慢一点也留回旋。河滩上的石头等着被踩稳，补上流程里的缺口再谈提速。" }
  },
  {
    id: "mj15", img: "mj15.jpg", arcana: "major", rank: "15", name: "恶魔", en: "The Devil", glyph: "😈",
    upright: { kw: "欲望 / 束缚 / 物质诱惑", love: "倒悬的火把照不亮路，占有欲越旺，人心越看不清。脖子上的链子看着粗，其实多半没扣死，先把条件摊开谈一次。分清吸引还是依赖，占有感强烈并不等于在乎得深。", study: "小天使被链子牵着走，消息一响就放下笔，自律一点点被蚕食。黑背景里看不见出口，先把手机放到另一个房间，用环境代替意志力。链环一节一节扣上，也一节一节能解开，从最小的一节开始。", career: "高薪像石台上那团火，好看，但倒着举的火把照不清前程。两个小人被同一条链牵着，竞业与考核条款要逐字看完再签字。锁链松紧只有自己知道，待遇之外先算清你要付出的自由。" },
    reversed: { kw: "觉醒 / 解脱 / 直面阴影", love: "小天使背上的翅膀本来就在，只是低头太久忘了能飞。火把正过来能照路，当初为何愿意被捆住，看清才不至于换一处再戴。挣脱之后别急着找下一个台子，先在空中站一会儿。", study: "锁扣松了才发现根本没锁死，拖延的恐惧大半是自己加的。火把倒转回来，看清逃避的触发点，压力立刻松了一半。石台上的裂缝不再吓人，把大任务拆成能跨过去的小格。", career: "脚链脱落是信号，不合理的制度已经开始显形，你不再装作看不见。走之前把退路和交接安排好，解脱要建立在清醒之上。恶魔的影子还在台上，但光照进了黑底，限制条款一条条可以谈判。" }
  },
  {
    id: "mj16", img: "mj16.jpg", arcana: "major", rank: "16", name: "高塔", en: "The Tower", glyph: "🌋",
    upright: { kw: "突变 / 崩塌 / 真相毕露", love: "闪电劈下来的那一刻，藏了很久的裂缝终于被照亮。王冠飞离塔顶，先放下身份与输赢，情绪最高点不作重大决定。废墟底下能看清哪些砖本就不实，重建不必照原样再垒一遍。", study: "塔身裂开的那道缝，正是死记硬背守不住的题。火从窗口冒出来，意外的失分暴露的是地基漏洞，先回到定义。碎石坠落有先后，错题按漏洞大小排优先级，重建理解比刷新题急。", career: "架构重组像那道闪电，虚楼不塌才轮不到你站稳。火舌卷着王冠飞走，头衔最不可靠的时候，先保核心业务与个人口碑。重建的窗口就在尘埃落定后，把复盘落成流程，别靠人情补位。" },
    reversed: { kw: "余震 / 幸免 / 抗拒真相", love: "雷声过去了余震还在，谁都不提的裂缝不算愈合。被甩落的王冠没人捡了，余震期先别急着许重大的承诺。地基重新砌稳之前，两个人轮流扶一段墙，比指责省力。", study: "这次侥幸没塌，不代表承重没有问题，漏洞仍在暗处。裂开的塔砖要一块块换，把暴露的短板列成清单按优先级补。窗口里的火熄了，别只庆幸跑得快，方法不改下次还会塌。", career: "危机缓释期，损失止住了，流程上的漏洞是这次最贵的收获。倾斜的塔身还能扶正，把复盘结论落成可执行的制度。坠落的人被大地接住，先安顿团队情绪，再谈责任归属。" }
  },
  {
    id: "mj17", img: "mj17.jpg", arcana: "major", rank: "17", name: "星星", en: "The Star", glyph: "⭐",
    upright: { kw: "希望 / 灵感 / 疗愈宁静", love: "头顶的大星倒映进池里，水面终于静下来。壶口缓缓倒水，像疗愈你的人被你温柔对待。在星光下聊聊各自的愿想，方向一致就多靠近。", study: "一柄壶往池里倒水，另一柄往土地浇灌，学习要兼顾输入和输出。八芒星照得清澈，脑子里的乱麻也理顺了。把那个遥远的目标拆成每天能做的小步骤，星光才照得进日子。", career: "星光落在两只金壶上，愿景与手艺要分两处落地。把作品集像果树那样一颗颗整理出来，愿想才有凭据。白鹤守在浅滩等鱼，耐心与准备一样都不能少。" },
    reversed: { kw: "迷失 / 信心受挫 / 灵感枯竭", love: "大星被云遮住时，别以为光已经熄灭。先给自己倒一小杯水，信心从最小的确定感攒起。白鹤挪去别处不是离开，你也不必守在原地空等。", study: "池里的星影晃了，先稳住呼吸再定目标。回到最基础的那页内容找回手感，方向是走着才清楚的。果树结果是一颗一颗来的，每天的小输入胜过熬夜的雄心。", career: "星光暗下来的时候，先别急着换赛道，先补自己的电。两柄壶都停了水，池子和土地会同时干裂。把目标缩到本季度能验证的一件事，让小小的胜仗重新点亮前路。" }
  },
  {
    id: "mj18", img: "mj18.jpg", arcana: "major", rank: "18", name: "月亮", en: "The Moon", glyph: "🌕",
    upright: { kw: "幻象 / 不安 / 深层潜意识", love: "月亮闭着眼，照不全整条小路，含糊期最易靠猜。别让犬与狼在夜里对叫，挑平静的时刻直接问清。把担心的事逐条写在纸上，想象在核实之后会缩小。", study: "螯虾从池底爬上来，藏着的漏洞迟早露头。把含糊处先标出来，回到定义和例题重打地基。月亮只露半张脸，知识也要查清另一半再做题。", career: "双塔之间没有月光，传闻与半截消息飞得最欢。事实成形之前只做能核实的事，往来一律留下书面记录。螯虾举着双钳，敏感事务上离抢功的人远一点。" },
    reversed: { kw: "拨云见日 / 恐惧消散 / 澄清", love: "月亮睁开眼，你以为吓人的路其实平坦。把最担心的那件事讲出口，想象里的严重性当场缩水。残余的不安若还在，就约定一个定期核对感受的方式。", study: "月光落进池里，原先打结的知识排到了岸边。把剩下的疑点列成条目逐个攻破，踏实感会持续回来。双塔之间的小路如今看清了，照着它走完这个考期。", career: "螯虾离了岸，浮出水面的隐情是这次最贵的收获。趁沟通顺当把顾虑谈开，含糊的规则一次问明白。余波未平之前少下重注，等结论正式落地再推进。" }
  },
  {
    id: "mj19", img: "mj19.jpg", arcana: "major", rank: "19", name: "太阳", en: "The Sun", glyph: "☀️",
    upright: { kw: "成功 / 喜悦 / 活力全开", love: "孩子张开双臂伏在马背上，欢喜就该坦率表达。把对方大方介绍给朋友，坦荡会让这份明亮维持更久。顺境里留一次真诚深谈，欢笑之外还需要彼此理解。", study: "孩子骑在白马背上不怕高，敢把目标定得更远。趁精力旺盛集中解决难题，同时守住睡眠这条底线。把这段顺利的方法与作息记录下来，低谷时照着恢复。", career: "墙外一排向日葵朝着光，个人的亮眼来自整队的托举。把功劳分给团队，顺境里攒下的口碑是日后的助力。热闹里留好备份与账目，别让细小隐患藏在强光背后。" },
    reversed: { kw: "延迟 / 虚旺 / 快乐打折", love: "云从太阳前走过，热度暂时降了一层，不必当结局。一句温和的话就能让温度回来大半，别让面子挡路。若总觉得快乐不够，先查有没有需求一直没说出口。", study: "把白衫上的太阳徽记放回日程表，用固定流程推进。把最意外的几道错题挑出来补根基，那里才藏着真分数。别靠当天的情绪决定学不学，阴天也要把小步走完。", career: "太阳晚升了半步，批复与反馈都比预想的慢。趁等待期把成本与细节复核一遍，稳一些反而落地更快。马背上的孩子收了笑，团队疲惫时别硬撑排场。" }
  },
  {
    id: "mj20", img: "mj20.jpg", arcana: "major", rank: "20", name: "审判", en: "Judgement", glyph: "📯",
    upright: { kw: "觉醒 / 召唤 / 复盘新生", love: "从棺木里起身的人手按胸口，像准备好重谈一次的你们。回应召唤不等于抹掉过去，先讲清准备改变的具体承诺。把旧问题正式重谈一次，结论说清而不是含糊翻篇。", study: "金光劈开云层压下来，越接近终考，复盘越有分量。把常错类型整理成一页清册，考前逐项过关。反复出错的题别放它继续睡着，它们决定你的涨幅。", career: "离开木棺的人朝光舒展身体，想换赛道先承认过去的账。结果落地前把材料与数据整理清楚，正式沟通时有凭有据。号角响起，考核结论即将揭晓，积累会被正式结算。" },
    reversed: { kw: "自我怀疑 / 回避审视 / 犹豫", love: "号角举在嘴边却不响，旧账每次争执都被翻出。要么正式谈一次给出结论，要么决定放下就从此不再翻。别把自我审判堆到对方身上，先把旧账与事实分开放。", study: "号角不响就永远卡在云端，回避审视的人等不到跃升。把复盘当成普通作业安排，只找原因，不给智商下判词。从最简单的一份旧卷开始，起身也需要一点力气。", career: "号角被云层闷住，犹豫才是这场考核里最贵的成本。提前把材料和数据整理清楚，主动请求一次反馈。错过一轮考核不算终局，补齐材料下一轮再呈上去。" }
  },
  {
    id: "mj21", img: "mj21.jpg", arcana: "major", rank: "21", name: "世界", en: "The World", glyph: "🌍",
    upright: { kw: "圆满 / 达成 / 新的视野", love: "少女在花环中央起舞，关系走到了圆满的节点。见家长或共同定居，值得认真庆祝一次，让圆满留下凭据。抵达之后仍需共同维护，把下一段愿望一起写进蓝图。", study: "两柄杖在怀中交叉，标记一个阶段的收官落定。先彻底休整一场，再带着更大的视野选下一站。把已有积累整理成作品集或申请材料，鹰会带你飞更高。", career: "项目全链路收尾干净，花环里的舞步别人看得见。把经验沉淀成方法并公开分享，更大的舞台由这些展示牵来。狮子与牛守着外围，前方的名声需要后方的流程接住。" },
    reversed: { kw: "未竟 / 差一步 / 迟迟不收官", love: "花环缺了一角未合拢，承诺总差最后一步。推迟要附上真实原因，再给一个明确的时间点。执杖的少女迈不出舞步，不安全感不说清就成了借口。", study: "花环没合拢，终检值得单独安排一轮。把格式与细节照清单逐项核对，失分集中在最后一段。别急着赶新周期，收尾质量不过关，旧问题会跟着重来。", career: "鹰已在环外展翅，先把这一环扣上再谈更大的舞台。列出未闭环的事项逐项清账，最后一环最贵也最值钱。结项材料与交接文档没做完，成果就难真正落地。" }
  },
  // ===== 权杖 Wands (wa01 - wa14) =====
  {
    id: "wa01", img: "wa01.jpg", arcana: "wands", rank: "A", name: "权杖王牌", en: "Ace of Wands", glyph: "🔥",
    upright: { kw: "灵感火花 / 激情 / 新起点", love: "权杖抽出新叶，心动也是有形状的信号。手从云里伸出来，把邀约说出口，约个具体的日子。树根先抓紧大地再抽芽，快也要留一层底子。", study: "杖头忽然抽芽，对一门学科的钻研欲到了。趁高峰期把入门框架搭完，窗口只开几个星期。新叶是一片片长的，把兴趣过成习惯才算落地。", career: "新杖到手就扎了根，灵感与机会同时出现。把第一步拆成本周能交付的成果，让热情变成看得见的进度。计划别只在脑中推演，先迈出一步再边走边调。" },
    reversed: { kw: "熄火 / 冲动 / 时机未到", love: "杖上的叶子打了蔫，热情来得快去得也快。给彼此两三周冷静期，看看想念是习惯还是真心。火苗被风吹凉时，先减少联系的密度再谈别的。", study: "抽出的嫩芽枯了，三分钟热度烧完只剩空壳。把目标缩到不可能失败的一步，靠规律重新点火。熄火期硬加时长只会更厌学，先守住能完成的量。", career: "杖身锯口还新，芽没冒出就急着宣布开局。先验证方案里最没把握的一环，手的力道不如根的稳固。人手与预算未到位就再等等，晚出发好过中途散伙。" }
  },
  {
    id: "wa02", img: "wa02.jpg", arcana: "wands", rank: "2", name: "权杖二", en: "Two of Wands", glyph: "🌐",
    upright: { kw: "规划 / 远见 / 掌握全局", love: "手里的地球仪像两人的未来，值得摊开共商。先各写一份蓝图再对照，差异处藏着没说出口的顾虑。海上那两叶帆还在远处，定好下次核对的时间再推进。", study: "地球仪在手里，脚却站在城墙上，规划要兼顾高度与立足点。给每个阶段设一个可检验的小目标，像在海图上标港口。他把目光越过海面，路线定了就认真走完一两个月再调。", career: "手里的地球仪要转着核对，落子的位置靠数据说话。扩张前先确认后方团队接得住，别让自己成为唯一支撑。出发前把交接名单与培养计划列清楚，后方稳了前方才敢走远。" },
    reversed: { kw: "犹豫 / 固守 / 畏于未知", love: "石狮守着原地多年，别让关系也站成一座雕像。回避的背后有具体的顾虑，讲清比沉默更能松动僵局。可以先试一次不谈承诺的共同计划，比如短途出行。", study: "两根杖已经插在城头，别再拔起来换个方向插。先给每个方案定一个考验期，再谈路线是否调整。哪怕选次优的路完整走完一轮，也胜过站在城头比较。", career: "城头的人望着地球仪不上船，蓝图就只是球体。试着认领一次小规模的拓展，先迈小步再谈版图。把熟悉业务做成可复制的流程，腾出人手再接下一单。" }
  },
  {
    id: "wa03", img: "wa03.jpg", arcana: "wands", rank: "3", name: "权杖三", en: "Three of Wands", glyph: "⛵",
    upright: { kw: "拓展 / 初果 / 静待远航", love: "海上归帆渐近，像陆续传来的答案。展望期容易理想化对方，把可能出现的分歧早点摆开。感情能否落地，看你们第一次共同处理现实问题的样子。", study: "崖上的人望着远帆，课内扎实之后该把眼光放出去。向外的机会反馈周期长，投递后一两个月没动静属正常。三柄杖稳稳插在岸边，手里的功课别松。", career: "出海的船带回第一笔订单，也带回市场的口信。趁势追加投入并盯紧交付，把首批客户做成长期伙伴。把回款周期与沟通成本算进预算，扩张的节奏才踩得稳。" },
    reversed: { kw: "受阻 / 短视 / 回报延迟", love: "帆影在海平线迟迟不见，约好的计划一再推迟。坐下来核对双方的时间表，比站在崖边空等有用。浪一次次拍打崖脚，披风凉了，先下山添件衣。", study: "三柄杖还立在岸边，攒下的底子不会作废。回头审视整条备考路线，先校准方向再重新发力。调整见效要到下一轮模考，别在半途又一次改道。", career: "谈妥的合作迟迟不签，远方市场不按预期回应。把受阻环节逐条复盘，分清是渠道问题还是需求错配。回款与订单延迟时设一条止损线，再等一轮而不是加倍投入。" }
  },
  {
    id: "wa04", img: "wa04.jpg", arcana: "wands", rank: "4", name: "权杖四", en: "Four of Wands", glyph: "🏡",
    upright: { kw: "里程碑 / 安定 / 欢庆时刻", love: "白裙与金衣在门下相视一笑，谈婚期前先确认双方都愿意走进同一扇门。筹备庆典时把彼此的付出逐一说出口道谢。婚礼之后谁做饭谁记账，提前分工才安稳。", study: "先给自己一个像样的奖励，门楼是这轮复习收官的牌坊。把高效周期的时间表原样抄下来，日后照搬。归零之后从错题最薄的那一段重新起步。", career: "团队在门下举杯，功劳要当场分给每位伙伴。把这次的流程写成模板，留给下一队人少走弯路。庆功时答应的资源记得落成文字。" },
    reversed: { kw: "根基不稳 / 未安 / 庆祝落空", love: "杖门歪了一根，喜帖便不好发出去，婚期与房款谈不拢时先缓一缓。别用排场掩盖分歧，把卡住的那件事拆开细谈。两家对家的想象不同，先统一自己人再坐下来议事。", study: "门楼立不稳是因为柱脚埋得浅，综合卷一测就露出被跳过的薄弱章。列出漏洞按提分快慢排序，庆功延后别赌气。歪门下站久了会焦虑，把目标缩到每天一页真题为止。", career: "四根杖有一根裂了缝，交付看似完成，尾款与遗留问题还挂着。把复盘排在庆功前面，先堵漏再开席。口头共识留不住人，落成新版流程才算堵住。" }
  },
  {
    id: "wa05", img: "wa05.jpg", arcana: "wands", rank: "5", name: "权杖五", en: "Five of Wands", glyph: "⚔️",
    upright: { kw: "竞争 / 磨合 / 观点交锋", love: "五根杖在半空交叉却不伤人，小吵小闹是磨合，把在意的点说透。蓝衣与红衣各守一边，生活习惯冲突时轮流举证，别抢着挥杖。吵完当天用一句话确认结论，防止旧仗重打。", study: "场中杖影交错如比试，把同窗当镜子而非对手，切磋最能暴露盲点。小组研讨时每人先讲一条论据，不许插话。被带乱节奏时回到自己的错题本上扎营。", career: "五根杖在同场比拼，多人争一个机会时，把自己那根杖握得最稳。方案擂台先亮数据，嗓门大不等于杖法准。赛后复盘对方方案里可学的部分，输也输一层皮。" },
    reversed: { kw: "内耗 / 回避 / 无谓之争", love: "杖举久了都累，为吵而吵的循环里，先叫停的人是给理性让路。同一件旧事第三次拌嘴时，停下来找源头。约一个暂停手势，冷却半小时必须回场谈完。", study: "五根杖打成一团乱麻，恶性内卷耗掉深夜，效率比名次先垮。比较之前先问自己要什么分数，别在缠斗里忘记举杖的理由。退出混战后拿自己的历史成绩当标尺。", career: "杖杖相缠谁也挥不出去，内斗的团队先停下来谈分工。找一个外部压力，一致对外最快解结。谈规则时把利益摆桌面，和气才不是忍气。" }
  },
  {
    id: "wa06", img: "wa06.jpg", arcana: "wands", rank: "6", name: "权杖六", en: "Six of Wands", glyph: "🏆",
    upright: { kw: "凯旋 / 认可 / 众望所归", love: "白马佩着花环缓行，恋情公开收获满街好评，甜也记得回到日常。高举的杖是承诺的旗，凯旋之后把功劳分给陪你走过低谷的人。棕榈夹道的大路宽敞，被祝福的关系更要守住两个人的私下节奏。", study: "头名骑白马过街，表扬到手时把这次奏效的时间表原样留两周。随行五人各持一杖，同学来请教时讲题，讲得清才是真会。大道尽头掌声会停，趁士气正盛把下阶段目标写在计划首页。", career: "白马路过之处人群随行，士气正盛时提资源申请最容易批。杖举得最高，晋升名单念到你的名字，领奖台先谢团队伙伴。棕榈树影落在凯旋路上，把项目数据归档，下次竞选有实打实的凭据。" },
    reversed: { kw: "自负 / 落选 / 期待落空", love: "马背上的人只顾挥杖，忘了身后随行早已散开，面子赢了里子空。桂冠歪了先扶正心态，落选的祝福没到，别拿冷淡试探对方。凯旋街空无一人，坐下来谈一次走心话，比十张合照管用。", study: "白马掉头走离人群，气馁时别把热爱一起丢掉，名次只是快照。名单上没有你的名字，桂冠没戴上，先把失分卷子拆开看。随行散了队，漏洞却露了出来，按错题类型补最集中的那一块。", career: "捧杀如烈日照桂冠，夸奖声里藏审视，得意时少说多做。随行杖阵缺了一角，团队功劳独吞一次，下次就没人同行。花环枯萎提示筹备不足，把差距拆成半年可补的项再竞选。" }
  },
  {
    id: "wa07", img: "wa07.jpg", arcana: "wands", rank: "7", name: "权杖七", en: "Seven of Wands", glyph: "🛡️",
    upright: { kw: "坚守 / 捍卫 / 以少敌多", love: "他手里只握一柄杖，却站得比六柄插地的都稳。感情被亲友议论时，先分清哪些声音值得答。守立场不必拔高嗓门，把两个人的日子过成看得见的样子。", study: "六柄插地的杖像六个质疑声，你手里那柄才作数。模考起伏时守住自己的计划，比追着别人改更有效。把质疑写成清单，一柄一柄处理，别一次全揽进怀里。", career: "一人立于岗顶，六柄插地像六个来挑战的位置。竞标或晋升时，把已有成果一柄一柄亮出来。优势在你手里，守成比抢攻更需要稳住重心。" },
    reversed: { kw: "溃退 / 疑惧 / 放弃立场", love: "杖从手里滑下去的瞬间，防线先在心里塌了。被议论到想退缩时，先问这一局值不值得守。若已疲惫到握不住，退下阵来休整并不丢人。", study: "六面来风时先护住主科，那是你手里那柄。守不住所有的题，就守住最关键的失分点。越想讨好所有老师，自己的节奏越容易散。", career: "精力有限时，把杖收回而不是插满山坡。防线被轮番试探时，硬扛不如挑重点回击。位置守得太累，先检查是不是站错了高地。" }
  },
  {
    id: "wa08", img: "wa08.jpg", arcana: "wands", rank: "8", name: "权杖八", en: "Eight of Wands", glyph: "✈️",
    upright: { kw: "迅速 / 进展 / 势如破竹", love: "八根杖斜掠金空，消息一条接一条，快也要留一次面对面深聊。并肩坐在倒木上看杖雨，进度飞快时抽空核对三观是否同向。河谷的水走得急却不喧哗，热恋期过后仍主动约见才算稳。", study: "杖如飞矢各走一道，多门并行时每门留一页进度单防漏项。仰头数杖的少年提醒你，趁手感火热集中歼灭积累的难点。银发旅伴安静在侧，快节奏里安排每天一段慢整理，错题当天消化。", career: "八杖齐发不留空档，多线项目用清单排优先级，逐个击破。天空只闻杖声，沟通一律落书面，口头决定最容易在半路走样。河谷开阔水路分明，每天收工花十分钟清点发出的消息防误会。" },
    reversed: { kw: "延误 / 混乱 / 急则生错", love: "飞杖迟了几道，回复慢了些，追问之前先给脑补设一个时限。一人想快一人想缓，并肩的倒木坐出了距离，把期待摊开谈。云影遮住河谷，误会生起时当面问一句，胜过屏幕后连发十条。", study: "杖飞得太密互相磕碰，贪快做完不核对，小错越攒越多。倒木上的行囊鼓胀，资料囤得再多，做对一题比多刷十题划算。河流改了道，期限报得太满就如实改一个，兑现比速度值钱。", career: "八根杖堵在半空先后坠落，各环节不是延期就是返工，先停催办。旅人等杖落地才动身，延误发生后同步确切的新节点，别只道歉。行囊共用要分工清点，多线程里谁接哪条线，白纸黑字写清。" }
  },
  {
    id: "wa09", img: "wa09.jpg", arcana: "wands", rank: "9", name: "权杖九", en: "Nine of Wands", glyph: "🤕",
    upright: { kw: "韧性 / 警觉 / 黎明坚守", love: "头缠绷带仍拄杖而立，受过伤再爱时，边观察边给机会。八根杖排成自家篱墙，底线温和而清楚地说出来，设防不等于拒绝。丢盔在地是卸下面子，把上一段留下的警觉讲给对方听。", study: "带伤拄杖也不离场，冲刺期靠日程和惯性也要走完当天计划。石墙上八杖列队，把错题按出错频率排一遍，比刷新题见效。弃刀于地，末段别再开新资料，旧题吃透足够撑到考试。", career: "九杖成阵守一道墙，久战疲惫时把重要交付留好备份和证据。头盔落地人未倒，口头共识易忘，每轮沟通落成书面记录。断刀插土不再用，拉锯已久就别指望奇招，稳守流程防线。" },
    reversed: { kw: "耗竭 / 疑心 / 放下执防", love: "九根杖守成孤墙，对方靠近你后退，正常的试探被当成敌情。盔甲丢了就别再捡，卸下防备从一件小事试一次信任的成本。长期独扛让帮忙无处下手，给爱人留一个参与的入口。", study: "杖还立着人先垮了，硬坐书桌前效率尽失，安排一次完整休整。满墙九杖全是防线也全是负担，砍掉一半科目先保住能拿的分。弃盔表明不想再防，复出第一天只排轻任务过渡，别猛冲。", career: "九杖围成草木皆兵，紧绷久了把正常反馈读成敌意，先休整。拄杖变扶墙，疑心最重时的判断偏黑，重要决定推迟到休假后。绷带该换了，把减负理由从扛不住换成保质量，上级更易点头。" }
  },
  {
    id: "wa10", img: "wa10.jpg", arcana: "wands", rank: "10", name: "权杖十", en: "Ten of Wands", glyph: "🥵",
    upright: { kw: "担当 / 重压 / 咬牙前行", love: "横杆上十根杖全压一肩，现实与情绪都揽过来时，累也要说出口。低头看路的人看不见同伴表情，每周留一次不谈压力的并肩散步。步子慢而稳是担当，但亲密关系本该两人轮换扛杆。", study: "十杖捆在一条杆上，论文实习考试同压，按截止与分值排序。低头赶路如埋首题海，每完成一项划掉一项，可见进度抗焦虑。村道窄容不下快跑，不可逆的任务先办，能缓交的坚决后放。", career: "一人挑十杖如兼数岗，把超负荷如实呈给上级，付出要被看见。弯腰的弧度是专业，但最有成绩时提人手需求才谈得动。村庄在望，急活攒到你手里也要分先后，先办塌了会砸墙的。" },
    reversed: { kw: "卸责 / 崩溃 / 学会授权", love: "十根杖压弯了腰，怨气在小事上引爆，开口邀请分担要趁早。扁担咯吱响时别硬撑，把隐忍的具体事件说清，不攻击人格。对方手里也有一副肩，点明一件具体小事让他接过去。", study: "贪多的十杖勒进肉里，报了满打满算的课，学透的没几样。减法从解开一根绳开始，砍掉一半计划，核心科目优先吃透。低头的姿势久了会僵，做完减法后别因焦虑把砍掉的再捡回。", career: "十杖垂挂挡住两侧视线，事事亲过目，团队就养成了依赖。该解的绳结解出去，从风险最低的环节试放权，小失控不怕。弯腰太久直不起，交接时把判断标准一并讲明，事才不会回流。" }
  },
  {
    id: "wa11", img: "wa11.jpg", arcana: "wands", rank: "page", name: "权杖侍从", en: "Page of Wands", glyph: "📜",
    upright: { kw: "消息 / 好奇 / 初试锋芒", love: "仰望星空的少年告诉你，好奇心牵着升温，别急着要结论。杖头抽出的嫩叶像新消息，暧昧邀约来了就大方应一次。脚边火蜥蜴安静发光，热度要观察几日，追问太急反而聊凉。", study: "少年仰头看星，不懂就问别怕露怯，新人提问不招人烦。火蜥蜴蹲在脚边不跑，每学一块用自己的话复述一遍。金字塔由石块垒起，框架立得住靠每天一小块完整闭环。", career: "持杖侍立的姿态接得住新任务，先确认验收标准再动手。脚边蜥蜴通体橙亮，第一版结果主动去要反馈，纠偏趁早。金字塔在远处等着，新人阶段多记录勤请教，隐形要求靠问。" },
    reversed: { kw: "画饼 / 分心 / 消息落空", love: "仰望的人不肯低头看路，忽冷忽热时把节奏拉回自己这边。杖梢的叶子蔫了，甜话说得再响，也先看行动落不落地。火蜥蜴的光忽明忽暗，别加倍热情去焐，观察一段再交真心。", study: "少年望着星星忘了脚下，行动是等待焦虑最好的解药。蜥蜴钻进沙里不见，通知迟迟不来时给查看设一个固定时间。贝雷帽上枝叶干枯，反复刷新页面的功夫够背十个词条。", career: "侍从的个头还撑不起大旗，空头承诺落在文字上才算数。杖顶新芽经不起沙漠的风，前景描绘得美，先问资源与负责人。火蜥蜴的光只够照亮脚边，先签小范围协议，用一次履约验证。" }
  },
  {
    id: "wa12", img: "wa12.jpg", arcana: "wands", rank: "knight", name: "权杖骑士", en: "Knight of Wands", glyph: "🐎",
    upright: { kw: "行动至上 / 热烈 / 大胆远征", love: "马蹄踏起烟尘，跨越距离的奔赴热烈，先享受再观察耐心。绿披风裹着红里子，热烈外面要有恒久的内里，谈一次长远安排。雪山遥遥在望，远征浪漫之余，把回家的日子也说定。", study: "策杖冲锋的姿态宜攻不宜守，锐气正盛时多啃新知识点。马尾带火照亮前路，攻新同时留固定整理时间，冲得快也记得牢。荒原辽阔任马奔，计划排到能坚持的强度，热度过后惯性推着走。", career: "骑士提杖出征，外派开拓接二连三，越跑越有干劲时归档战绩。燕群绕着盔顶盘旋，随行消息多线，书面记下每条承诺。雪山下的荒原等着路被踩出，趁冲劲把陌生门道录成清单。" },
    reversed: { kw: "莽撞 / 虎头蛇尾 / 中途转向", love: "马冲得太快看不清路况，被激情推着时，把重大决定往后放。火焰尾巴烧得旺也熄得快，承诺听听，重点看兑现了几件。飞鸟散尽马蹄仍急，别追着跑，站定看对方会不会回头。", study: "起手猛如烈马，跳过基础错题，热度一过就想弃考。缰绳攥太紧马会失衡，计划要排成能坚持的小节奏。铁甲闷汗不如卸甲，空洞期别硬冲，先睡足再按清单补课。", career: "杖指三处方向，马却只能跑一条，频繁换赛道等于原地踏步。燕雀惊散说明阵脚已乱，新方向用业余时间试跑一个月。雪山未近尘土先起，沉得住气才跑得过长途，验证过再全力切换。" }
  },
  {
    id: "wa13", img: "wa13.jpg", arcana: "wands", rank: "queen", name: "权杖王后", en: "Queen of Wands", glyph: "🌺",
    upright: { kw: "魅力 / 自信 / 统筹有度", love: "端坐王座手扶葵花杖的人从不刻意讨谁欢心，你吸引爱意靠的是自身的从容。头顶掠过的双鸟像两句悄悄的情话，听到就回应，别把主动示好晾在风里。王座两侧的石狮镇得住场面却镇不住关系，偶尔示弱比全程强势更亲近人。", study: "葵花杖朝上的人天生适合站在讲台前，小组里的主讲不妨就交给你。把要讲的内容像整理花枝那样提前修剪一遍，站上位置才不会临场卡壳。石狮扶手象征你压得住场，但自习的冷板凳仍要一天一天坐热。", career: "戴葵花冠的人走进会议室自带焦点，场合越重要越要稳住笑容慢慢开口。杖头的葵盘低垂却朝着光，资源从来聚向主动迎光的人，多去有人的局。绣裙上的龙纹是手腕也是底气，把人情账记细，事后一句跟进胜过当场十句寒暄。" },
    reversed: { kw: "善妒 / 专制 / 光芒黯淡", love: "葵花冠蔫下来时，人才会盯着别人裙上的光，疑心自己的花不开。橘猫受惊会躲，人被醋意追着问也会躲，把质问换成一句我有点不安。杖上葵花枯着也别丢掉，承认嫉妒不丢人，讲清楚了光芒才重新亮起来。", study: "目光总瞟向别人进度的时候，自己手里的葵花杖就握不稳了。裙上龙纹再繁复也要一针一针绣，别人的捷径看再多不如补自己的基础。冠上花瓣落了就落了吧，从最拿手的一科重新开考，找回掌控感再向外扩面。", career: "王座坐久了容易把独座当独裁，拍板之前先让反对的话讲完。石狮再威风也只是石雕，把决策的担子分给活人担一担，你才不至于累垮。绣裙华丽遮不住暗火，先安抚共事最久的伙伴，口碑要从内圈一点点修。" }
  },
  {
    id: "wa14", img: "wa14.jpg", arcana: "wands", rank: "king", name: "权杖国王", en: "King of Wands", glyph: "🌟",
    upright: { kw: "愿景 / 领袖 / 开创格局", love: "掌心托起金日的人心里有方向，感情里你肯领路也肯担责，这份笃定最动人。木杖立得笔直，约会的大事你有主张，但别把主张变成替对方写好的剧本。脚边黑螈安静伏地，引领不是压服，留一段沉默让对方把想说的话攒够。", study: "举日者看得远，长周期的复习计划正适合由你来统筹拆解。柱廊再宏伟也靠一块块石头垒，战略之外要亲自把最基础的习题做穿。帷幕狮纹提醒你身后有同路人，大课题里敢分工，别把全队捆在自己身上。", career: "托日于掌心的国王负责定方向，关键时刻敢拍板也扛得起结果。石柱之间站得稳，也要每月走下一次台阶，去听一线最真实的反馈。狮纹帷幔挂着的是家底，扩张前先清点人手与粮草，魄力要配上清醒的账。" },
    reversed: { kw: "武断 / 野心失控 / 刚愎耗竭", love: "掌中烈日偏了角度，照得人睁不开眼，你的主导让家里气压越来越低。帷幕上的狮子吼给自家人听最伤，重要的决定摆上桌面商量才有温度。脚边黑螈懂得蛰伏，你也学学等待，话说到七分留三分给对方开口。", study: "野心举得太高，脚下的书却没人翻，宏大计划最怕只停在嘴上。木杖该拿来丈量进度，每天第一件事排最枯燥的基础练习，做完再谈战略。黑螈贴地而行，学着从最小的章节啃起，先证明小事做得扎实。", career: "烈日悬得太近会灼伤人，独断的会议室里没人再讲真话。杖头磨得发亮也撑不起所有决定，给自己设一个诤友，坏消息听完再拍板。扩张的胃口大过账上的金光时，先算清现金流能支撑几个月。" }
  },
  // ===== 圣杯 Cups (cu01 - cu14) =====
  {
    id: "cu01", img: "cu01.jpg", arcana: "cups", rank: "A", name: "圣杯王牌", en: "Ace of Cups", glyph: "🍷",
    upright: { kw: "爱意涌动 / 新情 / 直觉敞开", love: "云中伸出的手掌托起满溢的金杯，心动的信号已经到位，只差你开口接住。五道泉水从杯沿泼出去，别把喜欢憋成暗流，一句真诚的问候就是第一股水。白鸽衔着戒指掠过天空，旁人递来的善意带着诚意，接住再慢慢验证合不合。", study: "托杯的手稳稳的，新科目入门就选这股心流正通的时段，效率最高。白鸽绕着杯子飞，灵感来了别让它飞走，手边备一本杂记随时接住。泉水多得盛不住，正像刚点着的兴趣，趁热把它接进固定的学习时段。", career: "金杯涌水是创意找上门的征兆，新机会带着心意而来，先确认它与你同频。手掌从云中探出，机会来时姿态要主动，伸出手才够得到杯脚。花园有墙才聚得住水气，热情落地要配一张排期表，别让它四处漫溢。" },
    reversed: { kw: "情感干涸 / 封闭 / 宣泄不畅", love: "杯口朝下时泉水浇不进池子，先承认自己也在干渴，再谈照顾对方。托杯的手酸了就放下，单方面的给予撑不起关系，把需要讲成具体的小事。白鸽停在半空等回应，总收不到信号的那一方会先飞走，别拿沉默试探。", study: "手托空杯也要稳，先把作息调顺，兴趣的潮水会随精力一起回来。泉水断流的日子，硬灌新内容不如回看已掌握的章节找回手感。池水见底就清一清塘，换一间亮堂的教室，情绪常常会随环境松动。", career: "金杯倒扣流不出水，重复消耗让热情外溢，先看清内耗的源头在哪里。托举的手垂下来时别硬撑体面，找信任的人谈一次真实的感受。白鸽衔来的消息没人拆，团队氛围偏冷时，先回应别人的求助再谈自己。" }
  },
  {
    id: "cu02", img: "cu02.jpg", arcana: "cups", rank: "2", name: "圣杯二", en: "Two of Cups", glyph: "🥂",
    upright: { kw: "伴侣 / 结盟 / 情投意合", love: "金与银两只杯沿相碰，第一次对上的眼神就懂了分量。你们不必来自同一片岸，肯各挪半步就够。若刚遇到聊得来的人，把这杯敬出去，别闷在心里发酵。", study: "溪两边的石头各踩一块才稳，文理互补也是同理。像两只杯子彼此靠近，找一个能互倒所知的搭档。别把合作变成对表比赛，碰杯的意义是交流不是胜负。", career: "一金一银两只杯相碰，像两份互补的方案正式签约。谈判桌上各让一寸，成交线就在水中央浮起来。找合伙先试小单，像先碰一下杯再饮尽。" },
    reversed: { kw: "破裂 / 失衡 / 各怀心思", love: "盘蛇的权杖立在水中，旧矛盾没被解开，只是被浪漫盖住。杯子还举着，却已经碰不到一起，距离是装不住的。把质问换成一句「我想谈一件事」，僵局才开始松动。", study: "小组里两人各举各的杯，配合成了形式。分工没谈拢就开工，返工比讨论更花时间。搭档进度不一时，先对答案再对节奏。", career: "契约的杯子歪了，口头承诺与纸面条款对不上。谈判陷入僵局时，先撤回半步再重新伸手。谈不拢就散，好聚好散留得住下次的路。" }
  },
  {
    id: "cu03", img: "cu03.jpg", arcana: "cups", rank: "3", name: "圣杯三", en: "Three of Cups", glyph: "🎉",
    upright: { kw: "欢聚 / 闺蜜 / 庆祝时刻", love: "三人举杯的草地上笑声最松快，轻松的团体局里容易遇见聊得来的人。三只金杯浮在半空没人急着碰响，聚会散场后单独多聊几句再看是否合拍。百合开在脚边并不张扬，朋友介绍的对象别因矜持回绝，熟人的背书也是加分项。", study: "三席人各托一盏杯，学习小组里人人有分工，热闹才不至于空转。中间白裙的姑娘戴花冠主持场面，轮流主讲的角色正适合主动认领。金杯举得高也要放得下，讨论完留一天安静自测，把所得落成分数。", career: "三只杯子在头顶亮成一小片星，庆功宴上露个脸，真诚敬谢比群发管用。举杯的手都空着托住杯沿，功劳散给每个具体的人，人气就是这么攒起来的。玫瑰在身后开得正好，士气正盛时顺势提新计划，通过率往往比平时高。" },
    reversed: { kw: "社交过载 / 小团体 / 欢庆散场", love: "杯子举得太久手臂会酸，应酬挤满了周末，二人的独处反而成了稀客。三只杯里若混进第四只手，暧昧的苗头要及早挑明，界限划清才算数。起疑时别当场质问，先讲自己的不安更容易把话谈开。", study: "聚会一场接着一场，自习的椅子坐冷了三张，玩乐邀约要学着婉拒。南瓜熟透会烂在地里，讨论所得当天整理成笔记，热闹才不算白闹。拖后腿的搭子早点说清分工，周日补一场安静互测，保住友情与进度。", career: "三杯酒下肚正事全忘，团建排满日程时，交付是最先掉线的那根弦。星裙和花冠自成小圈，站队的热闹里保持中立，把手头的活做漂亮。散场的草地只剩杯印，庆过一功就把精力放回正事，口碑靠作品续。" }
  },
  {
    id: "cu04", img: "cu04.jpg", arcana: "cups", rank: "4", name: "圣杯四", en: "Four of Cups", glyph: "😐",
    upright: { kw: "倦怠 / 无视机会 / 内观", love: "树下抱臂的人盯着脚边三杯发呆，递来的第四杯他偏不抬头，眼前人的好常被习惯遮住。三杯在手还嫌淡，倦怠多半是例行公事作祟，换一种相处场景闷局就破。云中递杯的手不打算收回，对新出现的好意先别急着拒绝，放一周再判断也不迟。", study: "抱臂坐在树下的日子谁都有，资料味同嚼蜡时，硬啃不如先合上书本出去走走。脚边三杯摆成旧套路，换一科或换种资料轮着来，新鲜感能帮你顶过平台期。天上递来的第四杯像一节新课，倦怠期至少看一眼再决定要不要上。", career: "三杯摆在面前还提不起劲，上门的邀约先别急着推，写清核心需求再答复。树下坐久了腿会麻，低潮期不宜冲动离职，先在本职里找一个新着力点。云中那只手只递一次，看准的谈话要主动去约，别让犹豫替你做了决定。" },
    reversed: { kw: "苏醒 / 把握 / 走出淡漠", love: "终于抬手去接第四杯，淡漠退潮之后，日常相处重新显出滋味。松开抱了许久的双臂，把搁置的约定重新提上日程，那次没成的约会就很好。三杯旧酒也能品出新味，别说忘了看见对方的用心，让回温从瞬间变成持续。", study: "抬眼再看脚边三杯，滋味和从前不同，卡了许久的地方开始松动。接住第四杯的手要趁热，状态回升时去攻最薄弱的章节，往往事半功倍。树下的位置可以挪了，换间亮堂的自习室，把苏醒的动力落成日程。", career: "第四杯入了手，犹豫许久的事应声落定，主动回应带来第一道转机。抱臂的人站起来了，当初犹豫的选项此刻看得更清楚，重新评估一遍。三杯仍在脚边没有凉透，被忽略的本职机会擦擦亮，先接住近处的杯子。" }
  },
  {
    id: "cu05", img: "cu05.jpg", arcana: "cups", rank: "5", name: "圣杯五", en: "Five of Cups", glyph: "💧",
    upright: { kw: "失落 / 缅怀 / 仍有留存", love: "披灰袍低头看泼酒的人，忘了桥上还立着两只满杯，逝去的哭完了记得回头。三杯红酒在地上洇成暗色，难过可以给它设一个期限，到期就转身。桥下溪水还在往前走，眼前人递来的关心别拿旧事当尺子量，对谁都不公平。", study: "地上的酒渍擦得掉，丢分处一条条查，把错题整理成清单比自责管用。盯着泼掉的三杯懊悔，分数只会再难看一遍，复盘先看桥上留着的两杯。灰袍子裹紧是自我保护，情绪最重的当晚别碰新内容，错题留到第二天再理。", career: "泼在地上的三杯是沉没成本，复盘会上先把它与残余的资源分开来列。低头久了会忽略桥上的两只金杯，团队里仍有人愿意配合，主动去请。罩帽遮脸谈不成事，把客观意外与自身可改的部分各归各账。" },
    reversed: { kw: "释怀 / 转身 / 走出哀伤", love: "把罩帽摘下来的那天，桥上两杯的金色第一次照进眼里。地上的酒干了，转身走上桥，带着学到的界限感投入当下的相处。两只完好的杯子正等着人，复联或新缘分出现时，先讲清从前的结打算怎么解。", study: "离开酒渍走上桥去，才发现基础比想象中牢固，错题本该翻篇了。桥上两杯还温着，用可见的小进步重建信心，复习表按梯度排。抬头能望见城堡了，目标重新变得清楚，薄弱科目排到精力最好的时段。", career: "转过身后桥上两杯格外醒目，被忽略的资源一件件浮出水面。酒渍留在原地就好，主动联系还能合作的伙伴，把复盘所得变成新方案。石桥比看起来结实，团队的信任还在，回归正轨先发出一封真诚的信。" }
  },
  {
    id: "cu06", img: "cu06.jpg", arcana: "cups", rank: "6", name: "圣杯六", en: "Six of Cups", glyph: "🧸",
    upright: { kw: "回忆 / 纯真 / 久别重逢", love: "跪地递花杯的姑娘笑得毫无所图，旧相识重逢时，那份熟悉的心动会回来。男孩双手将接未接，重逢的暖意要慢慢递，别一上来就讨答案。六只杯子盛满野花，纯粹的善意先给出去，心动自然有回流的河道。", study: "递出去的杯里花还带着露水，回看旧笔记时，新领悟会自己冒头。脚边满杯的花要一只只数清，温故之前先对照新大纲，把变过的部分标出来。像孩子仰头问为什么那样学，好奇心是最耐烧的灯，别嫌问题幼稚。", career: "旧日递过花的人如今捧着杯回礼，老同事的推荐是多年口碑的兑现。草帽姑娘蹲下身把杯子放平，老资源回聘时，条款仍要按当下的规矩重谈。六只金杯摆成一圈，往日的善意别急着收回，机会常从旧关系里长出来。" },
    reversed: { kw: "沉溺过去 / 停滞 / 向前看", love: "抱着盛旧花的杯子不肯放，新送来的那束就被晾在了男孩手里。六只杯都盛着从前，给新关系一段不比较的时间，让当下自己生长。聊天记录和旧物可以收进柜里，争执时别拿出来当武器，那样伤人最深。", study: "旧笔记里的花干了颜色，当年的经验先小范围验证，别直接套新考纲。六杯摆着不肯挪窝，资料该更新就更新，温故要建立在知新的框架上。少年早已长高，旧尺码的衣服穿不下，最新的真题才是新尺子。", career: "捧着当年的花杯不放，新局面里它摆不上体面的台面。草帽旧了遮阳就打折，吃老本的成绩单应对不了新的考核。池水不回头地流，怀念过去的辉煌，不如着手做出下一个拿得出手的代表作。" }
  },
  {
    id: "cu07", img: "cu07.jpg", arcana: "cups", rank: "7", name: "圣杯七", en: "Seven of Cups", glyph: "🫧",
    upright: { kw: "幻梦 / 选择 / 天马行空", love: "云端七只杯各闪着各的光，暧昧选项一多就别急着定心，先多见几次真人。戴冠的人头在杯中向你微笑，脑海里编织的完美剧本，爱上的多半是想象。披黑篷的那杯最沉，回避谈未来的对象先放一放，别替对方找借口。", study: "七只杯里宝石桂冠俱全，想考的证想学的领域排成一串，精力被选项稀释。发光那颗宝石最夺目，也别被它晃花了眼，先划掉与主线无关的杯子。桂冠代表荣誉也代表虚荣，选方向时分清是真心热爱还是单纯想赢。", career: "云里的杯子每一只都闪着前景，邀约琳琅满目时，先问预算人手与验收标准。冠中人头像画饼的承诺，讲得再好听也要落成白纸黑字的条款。城堡在山那头招手，畅想可以留着，本月先让一个最小的方案跑通闭环。" },
    reversed: { kw: "清醒 / 聚焦 / 拆穿幻影", love: "云散后杯子一只只淡去，滤镜碎掉的关系露出本来面貌，选择反而清晰。桂冠与蛇都收了戏法，踏实相处胜过梦幻剧情，接纳对方的不完美。山路尽头城堡显出轮廓，若确属根本不合，反复拉扯不如体面地把话讲清。", study: "七杯缩成一只，从漫天想法里挑出一个，复习计划重新变得具体。宝石的光收进口袋，给目标设时限和检验点，让想象兑换成分数。桂冠的诱惑放下吧，删掉多余的备考资料，只留一条主干走到底。", career: "雾气退去，包装精美的杯子露出空底，资源开始往实处集中。冠中人头不再许诺，少谈蓝图多交成果，清醒期的口碑比故事更稳。城堡有了确切的路线，集中力量推进最可行的项目，用验证过的结果说话。" }
  },
  {
    id: "cu08", img: "cu08.jpg", arcana: "cups", rank: "8", name: "圣杯八", en: "Eight of Cups", glyph: "🚶",
    upright: { kw: "主动离场 / 追寻 / 不满足", love: "八只杯子摆在山坡上，安稳给的东西都在，唯独心里还缺一块。红袍旅人握杖远行的背影提醒你先诚实，空缺别算在对方头上。想暂时一个人走走就明说这是充电，别让沉默被当成冷战的开场。", study: "第八只空杯放在线上，旧成绩已经喂不饱你，更难的领域在招手。带着已打好的基础走山路，不必把从前清零重来。转方向之前先去旁听几次，分清是真心向往还是只想逃离。", career: "红袍人离开八只金杯的背影，写着你反复说起的那句不甘心。走之前把存款、交接和退路逐项算清，追梦也要有粮草。若暂时走不了，先在现岗位认领一件真正想做的事。" },
    reversed: { kw: "徘徊 / 回归 / 不敢启程", love: "转身的人又走回杯边，想走走不了的拉扯最磨真心。决定再试一次就设个期限，像给山路立块里程碑。舍不得的常是投入本身，把账本合上再看前方河谷。", study: "八只杯子重新排好，退回旧轨道的人心里仍有不甘。想换的方法停在嘴边时，用一次低成本试听代替脑内推演。两边都不深耕最可惜，选定一条山路认真走三个月。", career: "走到山口又折返，离开的勇气攒不足，留下又天天内耗。简历像行囊悄悄更新，市场反馈会替你回答敢不敢。八只杯还在原地，走与留都要有个明确日期。" }
  },
  {
    id: "cu09", img: "cu09.jpg", arcana: "cups", rank: "9", name: "圣杯九", en: "Nine of Cups", glyph: "😌",
    upright: { kw: "满足 / 愿望成真 / 享受生活", love: "九只金杯码满木架，红衫人抱臂含笑，情感账户正丰盈。心里有愿望就坦然开口，像桌上玫瑰摆在明处。顺境最易疏忽对方，约一顿认真做的家常饭保鲜。", study: "九只金杯在架上排成三层，学习进度也终于顺了。红衫人抱臂的笑提醒你享受此刻，别急着焦虑下一步。把有效的方法抄进笔记本，日后低谷靠这份清单回血。", career: "木架上九杯满列，口碑与业绩这回一起到位。抱臂而坐的从容是底气攒出来的，谈晋升正合适。愿望成真也别松看守，把成果挂到明处备查。" },
    reversed: { kw: "奢求 / 空虚 / 得意过早", love: "杯架满而笑容发僵，物质热闹填不齐心口那个洞。把真实需求说出口，像把陶罐里的水倒进杯里。撤掉一场应酬，换两人安静吃一顿桌边的饭。", study: "架满九杯偏要数缺口，尝到甜头就停笔是最深的坑。小成就之后安排一次严格自测，查查深层的账。把心愿按架层拆成阶段任务，做完一格再庆祝一格。", career: "红衫人笑得过早，杯架未稳就先声夺人招来攀比。成果未定之前低调推进，喜讯公布太早容易招变数。像清点架上杯子一样检视开销，满盈感别滚成下季度负担。" }
  },
  {
    id: "cu10", img: "cu10.jpg", arcana: "cups", rank: "10", name: "圣杯十", en: "Ten of Cups", glyph: "🌈",
    upright: { kw: "家庭美满 / 和谐 / 情感圆满", love: "十只金杯在云空排成两列，一家人仰头同望，圆满有了形状。谈婚论嫁前把家务分工说清，别让和美败给琐碎。草屋炊烟日日要添柴，小仪式就是圆满的柴火。", study: "云上的杯子稳稳排着，家在后头，书桌前心无旁骛。无牵挂的阶段最适合攻长周期任务，一鼓作气啃硬骨头。向帮忙分担琐事的家人道谢，稳定的后方同样要经营。", career: "十杯高悬像彩虹拱门，团队如家的愿景要挂在明处。长期项目进了收获期，把经验写成方法传给新人。亲密时更要明确功劳分配，别让情分慢慢磨成怨气。" },
    reversed: { kw: "裂痕 / 理想落差 / 修复家人", love: "孩子在院里喊人，屋里却各说各话，小隔阂越积越深。从草屋那顿用心做的晚饭修起，先恢复对话再谈圆满。别等节庆才聚，平日一通电话比团圆饭更易破冰。", study: "十只杯隔着云够不着，家事的杂音飘进了书房。跟家里人约定固定时段，明说这段需要不被打扰。主动分担一件院里的琐事，换一夜安静再回书桌。", career: "天上的杯子排得整齐，屋里的人各想各的。表面客气盖住分歧时，请每个人会上讲一条顾虑。重建认可从一次公开感谢开始，裂痕正是修复的起点。" }
  },
  {
    id: "cu11", img: "cu11.jpg", arcana: "cups", rank: "page", name: "圣杯侍从", en: "Page of Cups", glyph: "🐠",
    upright: { kw: "好消息 / 童心 / 创作萌动", love: "少年低头看杯中跃鱼，青涩的示好笨拙却真诚。收到浪漫讯息时，从共同兴趣接话最容易延续。别急着定性心动，约几次真实相处看看成色。", study: "杯里跳出鱼的那一刻，灵感找上了爱发呆的人。备一本收集册，把闪现的创意落成小作品。新学科入门时多动手少空想，兴趣靠一次次正反馈续航。", career: "蓝袍侍从捧出带水花的消息，新芽般的提案被看见了。展示不完美的初稿时，附一组小数据让说服力站稳。海面帆船还在远处，机会靠岸前先把工位收拾好。" },
    reversed: { kw: "幼稚 / 情绪化 / 一厢情愿", love: "鱼跃出杯溅湿了幻想，爱的可能是自己写的剧本。忽冷忽热时别急着补剧情，先冷静观察一周。远处帆船迟迟不进港，与其岸边守望不如改约见面。", study: "情绪像杯中水晃来晃去，灵感来了才肯动笔的日子该收束。建一套固定小流程，先完成再等状态。状态差时拿机械性任务热身，笔动了灵感就跟上来。", career: "侍从的蓝袍还稚嫩，把委屈说给信任的人再上班。该来的消息像迷航的船，延迟失真后更要当面核实。等进度焦虑就直接问一次，比独自猜来猜去高效。" }
  },
  {
    id: "cu12", img: "cu12.jpg", arcana: "cups", rank: "knight", name: "圣杯骑士", en: "Knight of Cups", glyph: "🕊️",
    upright: { kw: "浪漫 / 邀约 / 温柔递情", love: "白马缓步而来，金杯高高举起，浪漫邀约带着仪式感。接连的邀约是明确信号，回请一次让关系平衡。享受深情时聊一回现实话题，看它落不落进日常。", study: "骑士以热爱为马，人文科目忽然开了窍。灵感像马步有快有慢，用固定时段兜住波动。斗篷上的杯月纹样是积累，每天抄一段喜欢的原文。", career: "执杯递出的姿态优雅，提案打动了会议室。情感之外附上执行表，浪漫才配得上落地。白马不疾不徐，被邀约时先问清责任再应承。" },
    reversed: { kw: "空想 / 暧昧 / 华而不实", love: "杯举得高却迟迟不递到手，承诺总差临门一步。情话满分的骑士也会绕路，看行动别看台词。再度失约时停止替他找理由，平静说出你的底线。", study: "白马驮着幻想跑，收藏的干货一题没做。每天留一小时扎实动笔，热爱需要练习承载。感动式资料停止囤积，今天就完整做一套真题。", career: "华美的杯照出空方案，一推敲就露怯。口头承诺迟迟不落袋，盯住节点与文字。马披银甲走得慢，成本与风险先测算完再汇报。" }
  },
  {
    id: "cu13", img: "cu13.jpg", arcana: "cups", rank: "queen", name: "圣杯王后", en: "Queen of Cups", glyph: "🦢",
    upright: { kw: "共情 / 直觉 / 温柔包容", love: "她低头看杯的安静模样，是被懂得的安心感。玫瑰冠下的人接得住情绪，也请你把自己的感受说出口。杯底的软垫提醒爱要垫细节，纪念日里一句回应就是回响。", study: "捧杯如捧一件易碎的灵感，感受力成了学习优势。用结构化笔记给直觉搭座，灵感才沉淀得下。裙摆浸水而不湿，情绪顺时学新章，不顺时复习旧页。", career: "王座安放在水中央，她在团队风波里稳得像定音鼓。矛盾起时出面调停最有效，但别接下所有人的情绪。玫瑰冠是软影响力，日常一句体谅就攒下口碑。" },
    reversed: { kw: "依附 / 情绪泛滥 / 耗竭", love: "杯抱得太紧，水满则溢，情绪泛滥先淹了自己。从每天说一个小需求练起，被照顾也是必修课。察觉自己在内耗就暂停付出，先问问自己累不累。", study: "湖水漫上座脚，杂事与情绪轻易入心，久久静不下。先写一段心情倒掉暗涌，再回到书桌前。设一段边界时段，安顿好情绪再安排任务。", career: "王后累了也要微笑，老好人的角色悄悄耗空杯子。给接活设一个额度，透支之后质量先垮。温和地拒绝一遍试试，天不会因此塌下来。" }
  },
  {
    id: "cu14", img: "cu14.jpg", arcana: "cups", rank: "king", name: "圣杯国王", en: "King of Cups", glyph: "🌊",
    upright: { kw: "情绪成熟 / 宽厚 / 驾驭波澜", love: "一手执杯一手握杖，他把深情与担当同时稳住。浪拍座基而面色不变，有分歧时先安抚再讲理。脚边那朵落下的玫瑰是软处，你的坦诚能让他卸下架子。", study: "海面起伏而王座不动，长线备考靠的就是这份定力。情绪不为一次分数起落，按周推进的计划别乱。偶有烦躁时先回看源头，别让一次波动变成弃考。", career: "惊涛只拍到座前，危机里他的语速就是全场定心丸。授权与培养要跟上，宽厚需要制度长久承载。金冠束发不遮眼，听得进坏消息的人才镇得住场。" },
    reversed: { kw: "暗涌 / 操纵 / 情绪失驭", love: "表面温和内里翻浪，冷暴力在沉默里涨潮。识别以退为进的控制，把话谈开才重见温度。杯里的水晃出来才看得见，别等涨到座前才说。", study: "心里暗涌表面按部就班，烦躁在悄悄偷走效率。规律作息是压浪的杖，睡够了再谈计划。别用完美日程压迫自己，留出弹性时段更可持续。", career: "喜怒藏得比海还深，驭下以柔术让人处处揣测。有心结就当面陈述事实，暗示与迂回只会加深隔阂。权杖举得太低照不亮航路，信息透明才养得出信任。" }
  },
  // ===== 宝剑 Swords (sw01 - sw14) =====
  {
    id: "sw01", img: "sw01.jpg", arcana: "swords", rank: "A", name: "宝剑王牌", en: "Ace of Swords", glyph: "🗡️",
    upright: { kw: "洞见 / 决断 / 理清真相", love: "云中伸出的手握剑直插草地，一场坦白局该落地。把话说透要挑双方平静的时辰，只陈述事实不带刺。一次说不透就约下一次，别让坦白变成审问。", study: "剑尖点地的那一下，像抓住核心概念的顿悟。趁热把逻辑用自己的话写一遍，灵感才算沉淀。框架比题海更快，隔天讲给自己听检验是否真懂。", career: "执冠之手把剑立正，理清乱麻的决断就在此刻。结论写成一页纸推进，别让共识在拖延里散架。决策落定就及时同步各方，信息差是方案变形的源头。" },
    reversed: { kw: "割裂 / 混乱 / 滥用锋利", love: "剑倒竖着映出寒光，气头上的话专挑对方痛处落。一句顶十句之前先停顿半分钟，思路该对着问题而非人心。说过的重话要认真道歉修补，别用沉默拖长冷场。", study: "剑身乱晃反光，越钻牛角尖思路越散。合上书默写记得的，先补基础漏洞再谈技巧。把当天目标缩成一个具体问题，专注才有落点。", career: "剑尖朝天站不稳，观望太久机会会顺草坡溜走。先把最有把握的几点书面敲定，细节在执行里补。已宣布的改动尽量别再翻转，公信力比一次优化值钱。" }
  },
  {
    id: "sw02", img: "sw02.jpg", arcana: "swords", rank: "2", name: "宝剑二", en: "Two of Swords", glyph: "🙈",
    upright: { kw: "僵局 / 权衡 / 蒙眼抉择", love: "蒙眼布系在额前，两柄剑交叉挡在胸口，你把想说的话也一并拦下了。想知道偏向哪边，可以约定各自把两条路的好处写下来，再一起念给对方听。头顶的月牙照不亮抉择，那就把蒙眼布松一寸，先看清手里剑柄的温度。", study: "两种复习法像左右手各握一剑，交叉在胸前谁也不让谁。蒙着眼刷题只会原地僵坐，先把两种方法各自的耗时摊开来看。石凳坐得凉，脑子不能跟着凉，给自己定一个只试一种方法的短周期。", career: "谈判双方各亮一剑，剑尖相抵，谁也进不了半步。蒙眼布挡住的是表情不是条款，先把分歧逐条记在纸上。月亮只露半边，信息不全时别给最终答复，约一个双方都能到的期限。" },
    reversed: { kw: "摊牌 / 破局 / 真相刺眼", love: "蒙眼布落下的一刻，交叉的双剑终于分开，摊牌就是这么一个动作。别在话说出口的当晚要结论，海风会吹散火气，明早再谈细节。摊完牌请把听到的话复述一遍，很多扎人的刺其实出在听错。", study: "眼布一摘，积压的新知识像海浪一样拍上来，先挑一科站稳。两柄剑分开放进鞘里，一次只学一条主线，支线等框架立稳再碰。破局后的头几天像刚离石凳，腿麻进度慢，那是换方向的正常代价。", career: "交叉的剑一分开，中间的空位就是新条款的落笔处。真相刺眼如剑光，先把最难的条款写进纪要，逐条核对再签。破局之后趁热把分工写清，别让剑再交叉回原处。" }
  },
  {
    id: "sw03", img: "sw03.jpg", arcana: "swords", rank: "3", name: "宝剑三", en: "Three of Swords", glyph: "💔",
    upright: { kw: "心碎 / 伤痛 / 直面哀伤", love: "三柄剑穿在心上，雨从乌云里落下来，伤心就让它下一阵。头几天只安排吃饭睡觉和找人说话，重话留到云散再讲。若决定谈开，把每柄剑对应的一件事写清，一次只谈一个话题。", study: "一次失利像一剑穿心，错题摊开在雨里，凉得刺眼。给自己限两天的阴天，哭完把试卷按知识点重排一遍。别在情绪最低时改学习计划，先让伤口结一层薄痂再动。", career: "坏消息传来像三剑扎胸，先把手头的事按紧急度排成一列。乌云压着雨往下落，通报团队时把已知和未知分开讲。云散之后复盘这轮应对，把管用的止损动作写进流程。" },
    reversed: { kw: "拔剑 / 复原 / 执痛不放", love: "心上的剑柄已被握住，拔出来会带出一声闷疼，疼说明在复原。别把拔下的剑再摆回胸前反复端详，旧事只谈一次就算谈过。再提起那次伤害时，换成说我需要什么的方式，剑就只剩剑柄没有锋芒。", study: "三柄剑一根根离开心口，重做旧错题就是拔剑的动作。剑拔净了不等于满分在即，从有把握的题目开始找回手感。伤口结痂处最痒，旧失分的板块反复回测才算真补上。", career: "穿心的消息成了过去式，把因果写成一份复盘笔记收进抽屉。别替拔下的剑找责任人，笔记里只留事实和下一步。余痛还在时少开长跑会，短会快决，让节奏替你护住旧伤。" }
  },
  {
    id: "sw04", img: "sw04.jpg", arcana: "swords", rank: "4", name: "宝剑四", en: "Four of Swords", glyph: "🛌",
    upright: { kw: "休整 / 静养 / 蓄势待发", love: "他把剑挂上木架躺进石台，暂停不是弃赛，是给思绪让路。盔甲没脱就睡了，想清楚再复出，复谈前各自列好最在意的事。石台边的百合开得安静，独处那几天把作息慢慢补回来。", study: "三柄剑高挂在木架上，一柄横在身侧，书桌也该有停战的架子。背不进的那晚就熄灯，记忆像睡着的骑士，在梦里自己归位。石台上躺平的是身体，醒着的该是计划，复出当天先做轻复习。", career: "项目按下暂停，像骑士躺上石台，剑归架，人归位。横放的那柄剑是随时可用的底气，把技能短板列成清单备着。对外只说节奏调整，等石台睡够再带着方案起身。" },
    reversed: { kw: "躁动 / 过劳 / 强行复出", love: "剑还挂在架上人就坐起来，冷静期没过就复谈，旧话会重演。盔甲没卸利索，先问自己急着开口是想念还是慌。真要用剑时手会抖，先把作息养直，再谈谁来让步。", study: "剑没挂稳就回书桌，一页书翻三遍字都没进脑子。架上的剑别急着全摘，每天先只领一小块任务练手。彩窗外的太阳晒到眼皮了，补觉和运动排在刷题前面。", career: "躺够了才起身，伤没好就冲上一线，小错会连着出。跟上级坦白限度不是卸甲，是把排期拉回可行的轨道。康复的标准看精力不看日历，撑满负荷只会再躺回去。" }
  },
  {
    id: "sw05", img: "sw05.jpg", arcana: "swords", rank: "5", name: "宝剑五", en: "Five of Swords", glyph: "🗯️",
    upright: { kw: "冲突 / 险胜 / 代价之赢", love: "他抱着两剑得意地笑，两个背影已披着斗篷往湖边走。阴云只盖住半边天，赢了立场输了温度，冷场比争吵拖得更久。下次话要压过对方前，先想想湖边那两个低头的背影。", study: "藏笔记使绊子的较量，像身后插进草地的剑，看着赢实则耗。把较量改成和昨天的自己比，每日错题统计是更稳的记分牌。险胜的名次要不得底线，取巧的空洞会在大考时漏风。", career: "抱两剑笑的人，身后是空了三柄剑的阵地。内斗赢来的位置，坐上去像踩在插剑的草地。争之前先算代价，公开的规则与事实是唯一的剑鞘。" },
    reversed: { kw: "悔悟 / 休战 / 放下胜负", love: "他把剑插回土里转过身，休战的第一步总得有人先走。停战后要把真需求讲明白，否则只是把问题按进泥里。轮流说一次各自的底线，像把剑一柄柄插回草地归位。", study: "抱着的两柄剑也放下了，退出比较那天书桌格外安静。走开的背影不必追，按自己的薄弱点重排课表。化敌为友不亏，约那个对手互相讲一遍各自的盲区。", career: "笑声收了，两柄剑递还回去，和解的窗口正开着。会面时摆明各自诉求，给离场的背影留一个回头的台阶。停战协议要有分工边界，防止插过剑的草地再被踩乱。" }
  },
  {
    id: "sw06", img: "sw06.jpg", arcana: "swords", rank: "6", name: "宝剑六", en: "Six of Swords", glyph: "⛵",
    upright: { kw: "渡离 / 疗愈之旅 / 渐入佳境", love: "六柄剑插在船舷当桅杆，伤还没好利索，船已经离岸。披斗篷的两个人靠在一起，过渡期少谈结论，多保持规律联系。云开处露出金色天光，到了新岸再给关系下判断。", study: "六柄剑立在舷边挡风，新流程先用满一个月再说。船上的孩子要抱稳，基础模块优先，支线等靠岸再碰。撑篙的节奏比水流重要，每日定量比猛冲更能渡过去。", career: "调岗的船离岸时，是非留在身后那片乱石滩。低头依偎的两个人提醒你，先安顿人心再谈新布局。撑篙的手不急着用力，过渡期少做重大承诺。" },
    reversed: { kw: "搁浅 / 旧患复发 / 无法启航", love: "船在原地打转，因为没谈清的旧账跟上了船。舷边的剑挡得住风，挡不住斗篷里那句没说出口的话。水再静也到不了对岸，启程前把旧账摊开当面谈完。", study: "换了资料船还是那条旧航线，方法不改就搁浅在原地。六柄剑成了栅栏困住视线，先自测定位真正的卡点。孩子还在舱里等，先把主干框架搭稳再谈拓展。", career: "行程一再推迟，旧阵地的问题正在乱石滩后发酵。舷剑的倒影晃了又晃，搁浅时先把遗留事项列成清单。交接人没定就开船，责任会泡进冷水里发胀。" }
  },
  {
    id: "sw07", img: "sw07.jpg", arcana: "swords", rank: "7", name: "宝剑七", en: "Seven of Swords", glyph: "🦊",
    upright: { kw: "策略 / 隐秘 / 智取变通", love: "他抱着五柄剑回望营地，心里那点算计月亮都看见了。留在地上的两柄剑是说得出的一部分，先分清你藏的是哪种。涉及承诺的事别学他夜行，当面说清比什么巧计都稳。", study: "抱走五柄留两柄，抓重点的策略也得看地基漏没漏。帐篷里的火还没熄，基础题要亲手过一遍再谈技巧。省下的功夫要还到暗洞里，智取的前提是账算得清。", career: "他不硬碰营门，抱着剑绕行，谈判也常有迂回的一手。两柄剑插在明处作幌子，情报却要走正规渠道核实。月亮底下枯枝横着，计谋要设一条不失信的底线。" },
    reversed: { kw: "败露 / 回头 / 弃暗投明", love: "怀里的剑快抱不住了，营地的帐子一顶顶亮了灯。赶在传闻之前自己开口，把隐瞒的初衷讲清楚。枯枝绊脚的时刻别推给别人，只讲事实和感受。", study: "押题的捷径在考场上露了馅，怀里的剑掉了两柄。回到课本从例题过手，踏实的分数才守得住。怀里的剑掉了才看清功夫掺了假，先补被跳过的部分。", career: "小算盘摆上了台面，同事开始掂量你每句话的成色。主动同步信息，比等败露后再解释体面得多。营门重新为你开时，别再抱着剑绕路走。" }
  },
  {
    id: "sw08", img: "sw08.jpg", arcana: "swords", rank: "8", name: "宝剑八", en: "Eight of Swords", glyph: "🪢",
    upright: { kw: "束缚 / 困局 / 画地为牢", love: "八柄剑围成一圈，剑与剑之间其实留着能侧身的空。手上的绳松得很，先把怕失去的事逐条讲出口。每周先在泥地外恢复一件爱好，无力感会退一层。", study: "她认定走不出这片泥地，像认定自己天生学不会那门课。围住的八柄剑数得清，不敢问的那道题才最占地方。剑圈外就是湖水与桥，每天只设一个必完成的微任务。", career: "流程与压力像剑插成一圈，动一步都怕碰到刃。眼睛被布蒙着时，先要一份书面的明文规定再行动。泥地里先守住已有成果，再挑限制最小的口子试一步。" },
    reversed: { kw: "松绑 / 觉醒 / 自解其缚", love: "眼布摘下的瞬间，她发现剑圈一直虚让着一尺。手腕的绳落在泥里，选择权原来从没交给别人。松绑后先想清楚要什么，再决定这段关系的方向。", study: "她迈出泥地第一步，剑圈只是响了一声没拦住。拖延已久的难题集中清一批，正反馈会跟着来。桥那头的城堡就是新目标，把我不行改写成还没会。", career: "围了很久的剑阵出现一道缝，僵住的局面有了出路。眼布一摘才发现，多数限制是自己默认签下的。计划拆成本周可见的进展，松动就坐实成结果。" }
  },
  {
    id: "sw09", img: "sw09.jpg", arcana: "swords", rank: "9", name: "宝剑九", en: "Nine of Swords", glyph: "😰",
    upright: { kw: "焦虑 / 噩梦 / 午夜忧思", love: "墙上九柄剑，多半悬在自己吓自己的念头里。深夜反复回放那句重话，天亮看其实没那么锋利。把担心说出口给对方听，剑就少悬一柄。", study: "越临近大考，墙上的剑越像没复习完的清单。焦虑最怕具体，把担心的科目一柄一柄写下来。熬夜刷题是把剑磨得更亮，睡够才收得住。", career: "还没发生的坏结果，已在墙上挂满九柄。别在深夜回复要紧的消息，凌晨的判断带着刃。把最坏情况写成一页纸，焦虑就从悬着变成可办。" },
    reversed: { kw: "释负 / 求援 / 晨光破夜", love: "九柄剑开始松动，说明你终于肯开口求助。旧账不必一柄一柄数完，先抽走最悬的那柄。睡不好的那几天，别急着做任何感情决定。", study: "焦虑峰值已过，剩下的剑是惯性在响。把错题本合上睡一周，再打开时剑都落了鞘。状态回升时先补最基础的一门，稳住手感。", career: "最难的阶段在松动，别在黎明前自己撤岗。向同事开口分担，绳套自己解不如找人搭手。把深夜的恐慌留成笔记，白天逐条销账。" }
  },
  {
    id: "sw10", img: "sw10.jpg", arcana: "swords", rank: "10", name: "宝剑十", en: "Ten of Swords", glyph: "🌑",
    upright: { kw: "谷底 / 终局 / 触底反弹", love: "黑布盖住全身，十柄剑已落地，这段结束确实发生了。别趴着追问谁错得多，先把自己从这段夜路上扶起来。给这段经历写一页收尾，像拔掉最后一柄剑再起身。", study: "成绩崩到不能再低，旧路子的碎片像剑插满后背。推翻要干净，资料方法与带路的人都换一轮。那轮日出给对照期指路，新旧方法比一个月再定。", career: "方案夭折或被迫离场，十柄剑齐齐落下，没有更坏的了。夜海尽头有船起帆，可迁移的技能和人脉先盘点。复盘写到归因层，别把十柄剑都算成自己的错。" },
    reversed: { kw: "复苏 / 拔剑重生 / 拒绝躺平", love: "背上的剑一根根拔出，还疼着，人已经翻了个身。别把拔下的剑再插回去，往事不必反复开庭。对方再示好时，先看剑有没有真的放下再开门。", study: "剑拔到第七柄，成绩抬头，旧坑都变成了路标。剑痕还在背上，回升期忌报复性加量。把教训写成清单贴在桌前，标出剑落过的每个位置。", career: "天幕裂开一道光，手里的活从冲锋改成补漏洞。翻身的船要等日出才起锚，先把补救讲给关键人听。东山再起像小船先在近海试帆，别一次押上全部。" }
  },
  {
    id: "sw11", img: "sw11.jpg", arcana: "swords", rank: "page", name: "宝剑侍从", en: "Page of Swords", glyph: "🔍",
    upright: { kw: "好奇 / 侦查 / 消息刺探", love: "山顶双手竖剑的少年提醒你，观察本身无错，关键在方向指向哪里。挑个自然的时机开口，把攒下的疑问换成一次坦率的交谈。好奇是好事，真实的答案在对话里不在页面里。", study: "新知识像天上被风推着走的云，越追越多。每天只锁定一个小主题，像双手握剑那样专注，深挖一米胜过广撒网十厘米。零散的发现当天归进笔记，信息才会沉淀成知识。", career: "侦查的价值在于站在坡顶看清局势，不在复述谷底飘来的闲话。新讯息随风而至，先核实来源再决定行动。多问一句依据与渠道，消息才能变成可用的判断。" },
    reversed: { kw: "多疑 / 嘴快 / 空谈八卦", love: "疑心一起，就像风把云层越吹越乱，越查越慌。偷看的手机屏幕不是该双手紧握的那把剑，划到深夜只剩自己吓自己。把疑问摆上台面问一次，比暗中侦查百次更让自己安心。", study: "收藏的经验贴堆得很高，像天上的流云壮观却没落雨。挑一份最薄的核心资料精读，一次深想胜过十次浅看。读完用自己的话复述要点，检验这把剑是真归了鞘还是仍在半空。", career: "嘴快把失真的传闻散出去，口碑跌得比山坡还快。转发之前先过来源证据与职责三道关口。已传出的失真消息要主动更正，越早澄清对信誉的损失越小。" }
  },
  {
    id: "sw12", img: "sw12.jpg", arcana: "swords", rank: "knight", name: "宝剑骑士", en: "Knight of Swords", glyph: "⚡",
    upright: { kw: "疾进 / 锐气 / 雷厉风行", love: "直球式的坦白像高举过头的宝剑，痛快却可能吓退对方半步。摊牌之后给这段狂奔留一段缓冲，让对方有上马回应的时间。盾牌上的星徽是诚意，适时把守护亮出来，比剑锋更打动人。", study: "冲新题的势头猛如奔马，思路利落下笔果断。粗心丢的分往往摔在脚下的裂地上，检查环节放慢十分钟就值得。连冲三天勒马一次，把错题与草稿归拢干净。", career: "改革如奔马过原，积弊一口气扫掉大半，效率肉眼可见地抬升。冲锋前确认人手与资源跟得上马速，快才踩得住实地。受影响的合作方逐个沟通过，阻力会像被风按弯的树服软。" },
    reversed: { kw: "冒失 / 攻击 / 横冲直撞", love: "带气的话像脱手的剑，没中靶先伤了最亲的人。马蹄最快的时刻逼对方表态，多半连人带马一起翻车。锋芒收三分再开口，诚意从来不需要靠音量说话。", study: "赶进度翻答案，漏洞全在脚下的裂地里。每天划出一段固定时间只复盘旧错，不碰新题。正确率先站稳，再去抽马加鞭，这个顺序不能反过来。", career: "横冲直撞地推事，事情是快了，沿路的同盟却得罪了一圈。开口前默问一句，这是为事还是为气。把异议者变成商量对象，盾牌这时比剑好用。" }
  },
  {
    id: "sw13", img: "sw13.jpg", arcana: "swords", rank: "queen", name: "宝剑王后", en: "Queen of Swords", glyph: "🧊",
    upright: { kw: "清醒 / 洞察 / 界限分明", love: "心事像王后面前湖面映出的雪山，清醒而不含糊。立界限的时候补一句背后的在意，冷硬的话也就有了温度。摊开的左手是接对方好意的，不只是用来握尺子的。", study: "每门课的脉络理成一张清爽的网，像湖水通着雪山那样分明。独自攻题虽强，把思路讲给别人听，输出的准确度会再上一层。右手竖剑的姿势提醒你，审清题干再落笔。", career: "椅背上的小鸟是个信号，沉稳之处才有真消息敢接近你。让当事人把话讲完再落剑，程序公道胜过结论正确。锋芒里留一分温度，敬你和亲你才能并存。" },
    reversed: { kw: "尖刻 / 冷漠疏离 / 一刀切", love: "旧伤化作刃，一句刻薄话逼退一个真心人。察觉自己在试探对方时，直接说出需求比刺出去管用得多。伤口养好后，从接住一件小好意开始练习，再温和地开口一次。", study: "揪着细节瑕疵推翻整本教材，分析变成了内耗。批判前先问这个细节是否影响结论，不影响就记下继续推进。定一个完稿时间，到点先交出去再慢慢打磨。", career: "标准高到容不下失误，同伴的好意也被呛回来。提意见时附上已认可的部分，对方才真正听得进去。把高标准公开成可执行的细则，苛刻就会还原成专业。" }
  },
  {
    id: "sw14", img: "sw14.jpg", arcana: "swords", rank: "king", name: "宝剑国王", en: "King of Swords", glyph: "🏛️",
    upright: { kw: "公断 / 理性 / 权威裁决", love: "争执讲逻辑，承诺算数，日子稳得像崖前的瀑布顺流而下。左手托着的圆球是责任，接了就稳稳托住不撒手。偶尔放下道理认领一次情绪，规则之外还要靠感受校准。", study: "跟方法严谨的引路人训练思维，体系像瀑布一样逐级成形。笔记以问题为纲整理，多问一层为什么再往下挖。框架是王冠而非枷锁，戴上它也要记得定期抬头。", career: "托球与执剑并重，一手管全局一手管分寸，大盘方向才稳得住。把裁决依据适度公开，下属执行时才不至于只猜结论。裁决前听听一线执行的难处，剑要冷，握剑的手不能冷。" },
    reversed: { kw: "严苛 / 权术 / 铁腕压制", love: "逻辑从来不是感情的替身，王冠暖不了冷掉的炉灶。赢了理也要试着输一句软话，主动认领对方的感受。察觉对方沉默时停下追问，先承认自己语气过硬。", study: "钻牛角尖就像崖顶那株枯树，挺得笔直却不再发新芽。别怕挑战权威观点，把依据找足再落笔。参考答案之外列一条自己的解法，对比两者的优劣。", career: "手里的圆球象征权威，拿来压人就是用反了它。察觉没人再提反对时，开一次只听取不裁决的沟通会。权力边界写清楚，透明的规矩自会替代铁腕的威压。" }
  },
  // ===== 星币 Pentacles (pb01 - pb14) =====
  {
    id: "pb01", img: "pb01.jpg", arcana: "pentacles", rank: "A", name: "星币王牌", en: "Ace of Pentacles", glyph: "🪙",
    upright: { kw: "机遇 / 种子 / 财富起点", love: "出现的缘分像云中巨手递来的金币，质地厚实，场合看着平淡。别因不够惊喜就松手，踏实的对象最经得起细看。把相处当泉水养花，按时赴约认真回应，信任自会生根。", study: "头一个月打基础养习惯，像泉池先蓄满水，花才有得浇。贪多嚼不烂，专注一门课做出成绩，光才会向一处聚拢。实操型的内容先动手跟练，比纯啃理论见效快。", career: "把这笔机遇当种子栽培，财势的苗才接得住后面的风雨。第一笔入账的去向几乎决定后续格局，先留储备再谈扩张。跑通最小闭环，验证模式比铺开规模更要紧。" },
    reversed: { kw: "错失 / 空想 / 根基未立", love: "云开处递来的金币只闪一下，盯不住就错过了。眼前的实在人值得放在心上，定期见面比等待心动更靠谱。写清楚择偶标准，一次只经营一段关系，踏实感才会回笼。", study: "课买了资料囤了，种子悬在半空迟迟不落土。拖延的根源常是目标太大，把任务缩到当天能完成的量。从手头最薄的一本开始读完，先建立最小的学习记录。", career: "悬在半空的金币不会自己落地，伸手的人才配谈收获。回报承诺越响越要多问凭什么，先用小额投入试水。把手头的小账管出章法，根基立起来才接得住下一班船。" }
  },
  {
    id: "pb02", img: "pb02.jpg", arcana: "pentacles", rank: "2", name: "星币二", en: "Two of Pentacles", glyph: "🤹",
    upright: { kw: "周转 / 弹性 / 收支平衡", love: "礁石上的舞步乱了不要紧，绳环还在，重新对拍就行。把相处认真排进日程，见面的频率与开销摊开商量。忙闲节奏不一致时，把想见的心思提前说出口。", study: "两枚币交替的诀窍不在手快，在眼睛始终盯着落点。几门功课同时推进，按难度与截止日期动态分配时间。给弱科多留一格缓冲，别把最基础的科目挤到浪边。", career: "浪头一高一低是常态，绳环画得圆，周转就不断。同时接手几摊事，靠的是随时重排优先级的手感。留出余力应对意外，两份进账分账管理才守得住。" },
    reversed: { kw: "失衡 / 超载 / 拆东补西", love: "抛着抛着一枚币落了地，冷落就是这样开始的。把关系也当成必须排的账，每周固定留一段不被打扰的时光。抱怨对方缺席之前，先摊开日程表看看时间被什么占据。", study: "脚下礁石本就窄，别再往绳环上多挂一枚币。砍掉一门暂缓一门，集中火力先啃下一科。按考试的远近重新排序，最不急的先放一放。", career: "船在浪里偏了航向，先收绳，再重新起势。几个项目互相占用预算，先把账列清停掉回报最弱的一头。进度撑不住就坦率说明，遮掩最伤信用，坦白能换宽限。" }
  },
  {
    id: "pb03", img: "pb03.jpg", arcana: "pentacles", rank: "3", name: "星币三", en: "Three of Pentacles", glyph: "🔨",
    upright: { kw: "协作 / 匠艺 / 专业认可", love: "石殿里三人各司其职，好的感情也靠分工成全。别让人只跪着许愿，起来一起凿才看得见进度。被夸的那块石头不会自己成形，功劳要分给同路人。", study: "像图纸与石料对上号，方法对了苦功才有形状。把大目标拆成一日一凿，拱门就是这样合拢的。请教老师如展卷核对，别自己闷头把石头凿歪。", career: "匠人、图纸、跪地者，三方到位工程才动土。手艺被看见的起点，是把交付做成可检验的样。提案前先对齐图纸，返工是最贵的协作成本。" },
    reversed: { kw: "返工 / 扯皮 / 各干各的", love: "图纸对不上凿子，两人的规划从一开始没摊开。一人跪着许愿一人闷头凿石，努力不在同一面墙。先停下来核对图纸，别用加班式的补偿掩盖方向错位。", study: "拱顶的币暗下去，是进度在提醒你先对标准。方法没对齐就猛凿，越努力越像返工的预备。找老师当面批改，比独自猜图纸快得多。", career: "三方各凿各的，墙砌歪了才想起看图纸。交付经不起验收，口碑比返工更贵。重新开一次对齐会，把图纸投影在墙上。" }
  },
  {
    id: "pb04", img: "pb04.jpg", arcana: "pentacles", rank: "4", name: "星币四", en: "Four of Pentacles", glyph: "🔒",
    upright: { kw: "守成 / 储蓄 / 稳握资源", love: "怀里的金币再暖，也别忘了抬头看看身边人的眼睛。守住之余也要舍得表达，别让稳定被误读成不上心。固定存一笔共同基金，偶尔安排一次超出惯例的小用心。", study: "脚边踩着的那枚也别忽略，基础分最怕从脚下松动。定期回顾旧笔记，把失分点归档，守住基础分的本钱。不冒进不贪难，先把出现过的内容吃透。", career: "头顶那枚币别让它滑下，站稳了才守得住四方。现金为王的阶段，把钱和人脉攥在稳妥处最抗跌。保守不等于不动，每年划一笔学习经费留试水额度。" },
    reversed: { kw: "吝啬 / 撒漏 / 松手的功课", love: "怀里的币攥得再紧，也留一枚递到对方手里。账算得越清两颗心离得越远，爱本来没法精确对账。先从一件不计价的小事做起，主动给一次不计回报的付出。", study: "脚下踩着的那枚最危险，它挡着你往前走的步子。给笔记做一次取舍，只留主干勤做输出，知识才能盘活。真正吃透一页胜过收藏十份，定期清掉用不上的材料。", career: "石凳本就冰凉，别再把自己坐成一座雕像。设一条固定的储蓄线，人情往来留出合理预算。漏财要先找出口，把固定支出逐项过一遍。" }
  },
  {
    id: "pb05", img: "pb05.jpg", arcana: "pentacles", rank: "5", name: "星币五", en: "Five of Pentacles", glyph: "❄️",
    upright: { kw: "困顿 / 匮乏 / 风雪同行", love: "彩窗的光已经照在雪上，别低头只数自己的脚印。难处摊开一起面对，两人共撑一段雪路好过各自挨冻。低谷期最忌互相埋怨，把困难当成两人共同对付的外敌。", study: "雪夜里先看清光从哪扇窗透出，再决定往哪边走。鼓起勇气敲开一扇门，一次请教可能少走半月弯路。经费缺口坦率摆出来申请，愿意伸手的人比想象中多。", career: "杖要拄稳，两个人挨着走，这段雪路就没那么长。保住现金流比争面子要紧，能屈能伸才有翻盘资本。求助时把打算说得具体些，有规划的人更容易被拉一把。" },
    reversed: { kw: "脱困 / 求援 / 看见窗内光", love: "雪在化，把对方的手从兜里拿出来牵着走。回暖初期别急着翻旧账，先一起庆一庆没散这件事。把共渡难关的经过讲开，下次风浪两人都知道怎么撑。", study: "回头看那扇亮过的窗，它就是你下次求援的路标。每补上一块知识就做一次输出，才算真正焊牢。把补漏的方法沉淀成笔记，趁势建立自己的求援网络。", career: "杖可以放下了，前面的雪路已经走出了脚印。转机初现先小步验证，别因一笔订单就急着加杠杆。困难期许下的承诺记下来，好转后逐一兑现路才宽。" }
  },
  {
    id: "pb06", img: "pb06.jpg", arcana: "pentacles", rank: "6", name: "星币六", en: "Six of Pentacles", glyph: "🤲",
    upright: { kw: "给予 / 资助 / 收支对等", love: "红衣人举着铜天平先称轻重，再伸手递币，付出也该有这杆秤。别把对方的付出当成地上散落的币，捡起前先道一声谢。爱情讲收支对等，这周你多走一步，下周就该换他主动。", study: "天平举过头顶的那只手提醒求学者，受人资助先量清自己欠的分量。前辈递来的资料就是掌中那枚星币，接住后要磨成自己的手艺。得到五分帮助就还出三分整理好的笔记，流动起来才不会干涸。", career: "资助方举秤如红衣人，审的是投入产出，你汇报时也该带这杆秤。拨款落地先立明账，每笔开销对应地上的币，枚枚有去向。项目结项后主动让利新人，资源才肯继续流向你。" },
    reversed: { kw: "不对等 / 附带条件 / 索取无度", love: "铜天平一旦歪了，递出的每枚币都成了压人的砝码。总跪着接币的人习惯仰视，付出多的一方也别站太高。把帮助标好利息慢慢逼对方低头才伤人，要求回报不算失礼。", study: "靠别人拖进度就像跪地的姿势，久了腿会麻，路也走不直。每学期设一笔自学的预算，减少对外援的依赖，秤砣才回到自己手里。伸手要帮助之前，先把自己卡住的位置指给对方看。", career: "带条件的拨款像悬在半空不肯松开的币，接之前先问清义务。发现自己只在输血不会收账，就给慷慨设个额度到期停一停。把援助换算成白纸黑字的条款，人情账走不远，明账才走得长。" }
  },
  {
    id: "pb07", img: "pb07.jpg", arcana: "pentacles", rank: "7", name: "星币七", en: "Seven of Pentacles", glyph: "🌱",
    upright: { kw: "等待 / 评估 / 长期主义", love: "扶杖的农夫仰头看藤上的币，果实未熟，急也急不来。别天天拨弄叶子查岗，隔些日子再去看一眼就好。约好每季度聊一次进展，把长线的耐心换成看得见的复盘。", study: "七枚星币挂在一根藤上，背完一章再摘一枚。投入换不来分数时先查枝剪叶，分清是方法错了还是时候未到。给自己定一个秋天的验收日，把大目标拆成每月一枚小币。", career: "投资像那株爬藤，账面平淡的月份，根系正往石墙下延伸。农夫没有摇树催果，回收期里少做小动作，多记观察笔记。设一个明确的评估节点，到期对照数据决定补投还是收手。" },
    reversed: { kw: "焦躁 / 歉收 / 及时止损", love: "藤上的币迟迟不落地，倚杖的人开始怀疑这片土。单方面浇水的委屈是真的，把委屈说出口别让它烂在根里。在心里划一个期限，到期仍不见回响就体面地放下那根杖。", study: "数来数去还是七枚币挂在原处，加量换不来产量就该停。愁完把错题摊开，查是理解断了还是练习虚了。有效学习时长先测一遍，砍掉藤上那些空叶，专注远胜过空坐。", career: "藤蔓上看着有币，摘下来全是瘪的，歉收的账要趁早摊开算。沉没成本像缠住杖尖的枯藤，先承认亏损才能松手。把盈亏线画在纸上，到期不达就砍投入，犹豫的成本按天计息。" }
  },
  {
    id: "pb08", img: "pb08.jpg", arcana: "pentacles", rank: "8", name: "星币八", en: "Eight of Pentacles", glyph: "⚒️",
    upright: { kw: "精进 / 匠心 / 熟能生巧", love: "錾星的手一下一下不落空，感情里的浪漫也藏在重复打磨的小事里。墙上六枚成品币都是一锤一锤攒的，别嫌日子单调。每周留一晚共同打磨一件事，比节日大礼更沉淀信任。", study: "工匠低头盯的是掌中那枚币，刷题时一次只锁一种题型，吃透再换。六枚挂墙的成品就是进度条，记下每天真正錾深的部分。阶段末拿模拟卷验一验火候，闭门錾得再美也要经得起检验。", career: "不抢风头的围裙工匠靠交付攒口碑，一件件扎实活儿就是墙上的币。每单收工留三条心得，攒够了机会会循着锤声找上门。作品挂到能被看见的墙上，精进才换得来回报。" },
    reversed: { kw: "懈怠 / 机械 / 敷衍了事", love: "锤子若不过脑地空落，星币錾不出花纹，走过场的关心也焐不热人。做一件超出惯例的小事，先把锤声敲出新节奏。墙上六枚币蒙了灰也没人察觉，倦怠要说出来别硬撑。", study: "笔记抄得工整如模具压币，错题却还是老几样。专攻錾不深的那几枚，把时间砸在不会的部分。用自测驱动复习，合上书能复述几枚才算挂住几枚。", career: "赶工交出的毛边币，錾纹浅得指甲一刮就掉，招牌正是这样磨没的。接不住的活儿坦白延期，返工成本远高过一次诚实沟通。每月给作品定一次质检日，糊弄的活儿自己会露馅。" }
  },
  {
    id: "pb09", img: "pb09.jpg", arcana: "pentacles", rank: "9", name: "星币九", en: "Nine of Pentacles", glyph: "🍇",
    upright: { kw: "富足 / 独立 / 享受生活", love: "园中女子不等人送花，自己已有满架葡萄，丰盈的人自带吸引力。园门虚掩着，自足不等于上锁，留一扇门别人才进得来。分摊账单时爽快不扭捏，经济独立让你在感情里敢选敢留。", study: "九枚星币在墙上排得整整齐齐，学有余力的人，知识也自成体系。驯鹰讲究耐心与节奏，温书也一样，按自己的步调驯服最难那门课。定期用真题检验这套方法灵不灵，葡萄年年熟，架子也要年年修。", career: "华服女子名下的收成都是长年攒的，收入结构健康，才睡得安稳。把盈余像挂币一样稳稳排好，留出半年开销的储备，再谈长线配置。猎鹰在腕而心不慌，接大单前先把风险驯熟，条款吃透再抬手。" },
    reversed: { kw: "虚饰 / 依赖 / 财务窟窿", love: "袍子再华贵也遮不住空荡的园子，用礼物堆安全感，堆不出真心。直接说出情感上的需要，别把在乎折算成对方买没买单。把重心放回自身积累，园子真丰收了，就不用伸手讨认可。", study: "墙上九枚币擦得锃亮，架上的葡萄却在烂，成绩虚高最怕这种对照。回到最基础的内容做自测，圈出烂果的位置，一颗一颗修剪。别学只会被喂养的鹰，离开答案单飞，才看得出真本事。", career: "账面风光如满墙金币，现金流却在悄悄漏，先盘账再谈扩张。对外报价留足实底，虚高的身价经不起一次认真的盘查。把窟窿堵好再装饰门面，账本干净，睡得比华服踏实。" }
  },
  {
    id: "pb10", img: "pb10.jpg", arcana: "pentacles", rank: "10", name: "星币十", en: "Ten of Pentacles", glyph: "🏦",
    upright: { kw: "传承 / 家业 / 基业长青", love: "拱门上的十枚星币是家底也是承诺，谈婚论嫁时把它们亮给彼此看。财务安排与家庭边界婚前聊透，像拱门砌石，缝对了才立得久。婚后与两边老人保持一碗汤的距离，体面留住了，摩擦自然少。", study: "远处的城堡是家族攒下的基业，前辈铺的路让你少走许多弯路。借势不忘自身用功，把家里的方法与资料消化成自己的习惯。每门功课定一条独立完成线，靠山前的石头也要自己搬几块。", career: "十枚币分列拱门两侧，家业的规矩是数得清的，制度先于人情。平台有积累，个人努力站在稳固底盘上放大，选赛道先看地基。把传下来的经验写成手册，让家业靠体系运转，而非靠一个人撑持。" },
    reversed: { kw: "纠纷 / 耗散 / 守业维艰", love: "门上的币数得清，心里的算盘却数不清，婚事卡在彩礼与房本上。把婚事与房产拆开谈，感情归感情，账目归账目，别烩成一锅。坐在长凳上闭目的老人无暇过问，小两口的分歧要自己先解决。", study: "总指望家里兜底的人，坐不稳那条长凳，成绩也撑不起那道拱门。把可用条件列成清单，然后独立规划，靠山也要自己会爬山。家族期望与个人方向冲突时，别争辩，拿实打实的成绩说话。", career: "人情的账压过了经营的账，拱门上的币一枚枚松动，内斗就是这样开头。股权与职责模糊是争端的温床，先定好拍板的人，再谈效率。资产缩水时体面最误事，及早止损才守得住祖辈的底子。" }
  },
  {
    id: "pb11", img: "pb11.jpg", arcana: "pentacles", rank: "page", name: "星币侍从", en: "Page of Pentacles", glyph: "🎓",
    upright: { kw: "勤学 / 实操 / 小额机遇", love: "少年双手捧币细细端详，青涩的认真比动听的情话更打人。约会守时、说到做到，幼苗般的感情靠一次次兑现小承诺长大。别急着要名分，像他盯星币纹路那样，先看清对方的人品细节。", study: "学徒捧着星币像捧着全世界的道理，从头练基本功，进度慢些也值得。把实习和访学的机会亲手做一遍，手上的记忆比书本更牢。白花满地的园子也要逐株辨认，学习计划切成每天可完成的小块。", career: "新人接小单如侍从托起第一枚星币，掂量它的分量，也掂量自己的耐心。把每件小事做出作品的样子，师傅和机会都在暗处看着你的手艺。主动把复盘记录给上级看，接住的小单会越滚越大。" },
    reversed: { kw: "拖延 / 眼高 / 学业分心", love: "捧币的手若迟迟不伸出去，再亮的星币也照不暖两个人。把远期约定拆成本周可见的小行动，做不到的事先少许诺。幼苗经不起没完没了的等待，按时浇水的人才有收成。", study: "课程收藏了一大堆，手里的星币却从没翻面看过一次。收藏夹不等于书桌，今天就把排第一的资料翻开读十分钟。进度不理想时别怪自己笨，回头查哪一步断了投入。", career: "眼高的人扫一眼草地便嫌花小，手低的机会就这样从指边溜走。限期把一件小事做出水准，舞台从来是用实力换来的。实操时怕脏怕碎就永远接不住币，师傅不会递第二枚。" }
  },
  {
    id: "pb12", img: "pb12.jpg", arcana: "pentacles", rank: "knight", name: "星币骑士", en: "Knight of Pentacles", glyph: "🐂",
    upright: { kw: "稳健 / 坚持 / 按部就班", love: "金甲骑士坐在马上不催鞭，慢热的人一旦认定就极长情。给直白的行动多一点回应，老实的深情更需要被看见。稳定的节奏偶尔要仪式提鲜，安排一次小小的出其不意。", study: "白马踏着犁好的垄沟一步步走，固定时间固定计划，把考纲一寸寸啃完。固定计划里留一格机动，某天状态差也不至于全盘崩塌。每月用模拟考校准一次方向，防止勤奋滑向低水平的重复。", career: "铁甲与盾牌护着的不是锋芒，是一份零失误的交付记录。适当汇报进度里的亮点，靠谱也需要被人看见。靠谱之余练一次快速响应，关键时刻提速更让人刮目相看。" },
    reversed: { kw: "迟滞 / 怠惰 / 原地打转", love: "马在原地踱步多年，约会的路线和流程早已磨平了热情。偶尔偏离熟悉的田垄，绕去没走过的街角，节奏就活了过来。主动约定阶段性的目标，一起完成件从没做过的事。", study: "守着旧方法打转，像白马绕着同一块田埂转圈，转得越久越晕。停下来重测薄弱环节，升级方法比延长时间更要紧。坐得久不等于学得进，改用结果倒推每天的有效时长。", career: "工期一拖再拖，犁好的田还没下种，老牛式的稳妥过了头就是迟滞。给交付设好提前量，留出时间试新，别拿稳妥当拖延的挡箭牌。每季度试着换一样新工具，盾牌的纹样也要与时俱进。" }
  },
  {
    id: "pb13", img: "pb13.jpg", arcana: "pentacles", rank: "queen", name: "星币王后", en: "Queen of Pentacles", glyph: "🌻",
    upright: { kw: "持家 / 务实 / 富足的照料", love: "王后把藤椅打理得妥帖，一桌热饭与一份家计清单，就是她的爱的语言。照顾之余也肯示弱，偶尔让对方来照顾你，关系才双向流动。把家务设计成两人搭手的日常，被共同需要的感觉最养感情。", study: "黄花冠下的王后深谙环境之道，书桌整洁、作息安稳，学习自然有土壤。像侍弄藤椅上的葡萄那样打理笔记，枝蔓理顺了，果子才结得密。状态好的时段留给最难的科目，家务琐事排在末尾。", career: "像喂猫喂兔那样按时按量，资源分配有定例，团队才不闹饥荒。把务实的成果量化呈现出来，柔和的手腕要配上清晰的数据。管家式管理的长处是流程，把经验写成清单交给团队复用。" },
    reversed: { kw: "失衡 / 操劳 / 物质焦虑", love: "阶前的猫兔都喂饱了，唯独王后自己眼窝发青，贤惠失衡就成了委屈。把隐形付出列成清单摊开，先让对方看见，再谈如何分工。委屈攒多了会变成指责，不如每天说一句真实的感受。", study: "杂事和他人的需求挤满日程，书案上的课本蒙了灰，像顾不上打理的藤椅。每天先划出一段不可侵犯的学习时间，其余琐事排队处理。生活里最搅状态的那件事优先处理掉，书桌才坐得安稳。", career: "事事亲力亲为替人兜底，自己长期超负荷，团队反倒学不会走路。列一张不该管的事项清单，把能授权的交出去，才守得住核心。对不合理的需求摇头，温和的边界比无底线的热心更长久。" }
  },
  {
    id: "pb14", img: "pb14.jpg", arcana: "pentacles", rank: "king", name: "星币国王", en: "King of Pentacles", glyph: "💰",
    upright: { kw: "稳健理财 / 成功 / 雄厚", love: "国王把星币平摊在掌心，房、账与日程都安排妥当，这是他的担当。享受安稳也别忘了谈心，物质之外再留一点柔软的位置。满桌大餐不如一次眼神交汇的家常饭，人在场才是关照。", study: "头戴嵌宝石王冠的人懂得，平台与资源是拿来成事的，不是拿来躺的。每月给自己定一个交付期限，把平台给的便利压成真本事。园圃修剪得整整齐齐，错题与笔记也要定期归置，用时才找得到。", career: "牛头扶手的王座坐得稳，靠的是多年判断准、出手稳的信誉积累。版图越大越要把情分与利益分开，让制度去批账，别靠个人圣裁。定期拨一笔长线预算，雄厚家底要用在十年后的赛道上。" },
    reversed: { kw: "贪婪 / 固权 / 铜臭短视", love: "金库越砌越高，家里的对话越来越少，礼物代替不了人缺席的晚上。从日程里挪出一整晚留给家人，温度比排场更能养感情。把财务安排适度向家人透明，信任比金库更值得加固。", study: "条件好反而松懈，成绩看着体面，底子全靠平台撑着，如铠甲下的虚胖。趁早做几次从零开始的自测，把资源真正炼成自己的功力。给自己设一段断奶期，独立跑通一个课题才见真功力。", career: "把既得利益当成牛头扶手死死不放，迟早被它顶下王座。拨一笔试错预算，舍得布局的人才守得住大版图。短视的贪念常始于一次违规操作，守住合规底线等于保住版图。" }
  }
];
